window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["WIS"]={"book":"WIS","editions":{"fin-biblia1776":[[1,1,"Rakastakaat oikeutta, te jotka maata hallitsette: ajatelkaa Herraa hyvyydessä,ja etsikäät häntä sydämen yksinkertaisuudessa.","Rakastakaat oikeutta, te jotka maata hallitsette: ajatelkaa Herraa hyvyydessä,ja etsikäät häntä sydämen yksinkertaisuudessa."],[1,2,"Sillä hän antaa löytää itsensä niiltä, jotka ei häntä koettele ja ilmoittaa itsensä niille, jotka ei epäile hänestä.","Sillä hän antaa löytää itsensä niiltä, jotka ei häntä koettele ja ilmoittaa itsensä niille, jotka ei epäile hänestä."],[1,3,"Vaan väärät ajatukset eroittavat Jumalasta, mutta koeteltu voima rankaisee tyhmät.","Vaan väärät ajatukset eroittavat Jumalasta, mutta koeteltu voima rankaisee tyhmät."],[1,4,"Sillä ei viisaus tule häijyyn sieluun, ja ei asu siinä ruumiissa, joka synnin alle annettu on.","Sillä ei viisaus tule häijyyn sieluun, ja ei asu siinä ruumiissa, joka synnin alle annettu on."],[1,5,"Sillä Pyhä Henki, joka oikein opettaa, pakenee epäjumalan palvelioita, ja lähtee pois vääräin tyköä, jotka synnillä rangaistaan, johon he joutuvat.","Sillä Pyhä Henki, joka oikein opettaa, pakenee epäjumalan palvelioita, ja lähtee pois vääräin tyköä, jotka synnillä rangaistaan, johon he joutuvat."],[1,6,"Sillä viisaus on niin hyvä, ettei se anna laittajan rankaisematta olla; sillä Jumala on hänen ajatustensa todistaja, ja tuntee totisesti kaikki hänen sydämensä ja kuulee kaikki sanat.","Sillä viisaus on niin hyvä, ettei se anna laittajan rankaisematta olla; sillä Jumala on hänen ajatustensa todistaja, ja tuntee totisesti kaikki hänen sydämensä ja kuulee kaikki sanat."],[1,7,"Sillä maan piiri on täynnä Herran henkeä, joka puheet tuntee, on joka paikassa.","Sillä maan piiri on täynnä Herran henkeä, joka puheet tuntee, on joka paikassa."],[1,8,"Sentähden ei taida se salattu olla, joka häntä rankaiseman pitää, ei pidä ohitse menemän.","Sentähden ei taida se salattu olla, joka häntä rankaiseman pitää, ei pidä ohitse menemän."],[1,9,"Sillä jumalattoman aivoitus pitää tuomiolle tuleman, ja hänen puheensa, Herran eteen, että hänen pahuutensa rangaistaisiin","Sillä jumalattoman aivoitus pitää tuomiolle tuleman, ja hänen puheensa, Herran eteen, että hänen pahuutensa rangaistaisiin"],[1,10,"Sillä kiivas korva kuulee kaikki ja laittajan häväistys ei ole salassa.","Sillä kiivas korva kuulee kaikki ja laittajan häväistys ei ole salassa."],[1,11,"Niin ottakaat nyt vaari, ettette häpäise, ja pitäkään kielenne pois parjauksesta; sillä mitä te salaisesti puhutte, ei pidä turhaan menemän; sillä se suu, joka valhettelee, tappaa sielun.","Niin ottakaat nyt vaari, ettette häpäise, ja pitäkään kielenne pois parjauksesta; sillä mitä te salaisesti puhutte, ei pidä turhaan menemän; sillä se suu, joka valhettelee, tappaa sielun."],[1,12,"Älkäät niin pyytäkö kuolemaa teidän erhetyksillänne, ja älkäät etsikö kadotusta kättenne töillä.","Älkäät niin pyytäkö kuolemaa teidän erhetyksillänne, ja älkäät etsikö kadotusta kättenne töillä."],[1,13,"Sillä ei Jumala ole tehnyt kuolemaa, ja ei hänelle kelpaa eläväin kadotus.","Sillä ei Jumala ole tehnyt kuolemaa, ja ei hänelle kelpaa eläväin kadotus."],[1,14,"Mutta hän on kaikki luonut, että ne olemisessansa oleman pitäis, ja mitä maailmassa luotu on, se on hyvä, ja ei siinä ole mitäkään vahingollista, ei myös helvetin valtakunta maan päällä.","Mutta hän on kaikki luonut, että ne olemisessansa oleman pitäis, ja mitä maailmassa luotu on, se on hyvä, ja ei siinä ole mitäkään vahingollista, ei myös helvetin valtakunta maan päällä."],[1,15,"Mutta vanhurskas on kuolematoin.","Mutta vanhurskas on kuolematoin."],[1,16,"Vaan jumalattomat pyytävät kuolemaa sekä sanalla että työllä; sillä he pitävät hänen ystävänsä, menevät pois, ja yhdistävät itsensä hänen kanssansa; sillä he ovat myös sen ansainneet§ että he ovat hänen omansa.","Vaan jumalattomat pyytävät kuolemaa sekä sanalla että työllä; sillä he pitävät hänen ystävänsä, menevät pois, ja yhdistävät itsensä hänen kanssansa; sillä he ovat myös sen ansainneet§ että he ovat hänen omansa."],[2,1,"Sillä he ovat jumalattomat, ja sanovat: meidän elämämme on lyhykäinen ja vaivaloinen; ja kuin ihminen on kuollut, niin on hän peräti loppunut §, ja ei ole ketään tunnettu, joka on helvetistä palannut.","Sillä he ovat jumalattomat, ja sanovat: meidän elämämme on lyhykäinen ja vaivaloinen; ja kuin ihminen on kuollut, niin on hän peräti loppunut §, ja ei ole ketään tunnettu, joka on helvetistä palannut."],[2,2,"Me olemme siis tapaturmaisesti syntyneet, ja menemme pois niinkin emme ikänä olleetkaan olis; sillä hengen vetämys on savu, ja meidän puheemme on kipinä, joka meidän sydämestämme käy.","Me olemme siis tapaturmaisesti syntyneet, ja menemme pois niinkin emme ikänä olleetkaan olis; sillä hengen vetämys on savu, ja meidän puheemme on kipinä, joka meidän sydämestämme käy."],[2,3,"Kun se sammutettu on, niin on meidän ruumiinne pois niinkuin nöhtä, ja meidän henkemme katoo niinkuin löyhkä.","Kun se sammutettu on, niin on meidän ruumiinne pois niinkuin nöhtä, ja meidän henkemme katoo niinkuin löyhkä."],[2,4,"Ja meidän nimemme tulee ajan jälkeen unhotetuksi, ja ei yksikään ajattele, mitä me tehneet olemme; meidän elämämme menee niinkuin pilvi, ja katoo niinkuin sumu, joka auringon paisteelta ajetaan pois, ja hänen palavuudellansa hajoitetut on.","Ja meidän nimemme tulee ajan jälkeen unhotetuksi, ja ei yksikään ajattele, mitä me tehneet olemme; meidän elämämme menee niinkuin pilvi, ja katoo niinkuin sumu, joka auringon paisteelta ajetaan pois, ja hänen palavuudellansa hajoitetut on."],[2,5,"Meidän aikamme on niinkuin varjo, ja kuin me tulemme pois, niin ei tulla jälleen; sillä on niin päätetty§, ettei yksikään pidä tuleman jälleen.","Meidän aikamme on niinkuin varjo, ja kuin me tulemme pois, niin ei tulla jälleen; sillä on niin päätetty§, ettei yksikään pidä tuleman jälleen."],[2,6,"Niin tulkaa siis, ja eläkäämme hyvästi, niin kauvan kuin me taidamme ja nautitkaamme elämäämme niin kauvan kuin me nuoret olemme.","Niin tulkaa siis, ja eläkäämme hyvästi, niin kauvan kuin me taidamme ja nautitkaamme elämäämme niin kauvan kuin me nuoret olemme."],[2,7,"Me tahdomme täyttää meitämme parhaalla viinalla ja voiteella, älkäämme unhoittako kevätkukkasia;","Me tahdomme täyttää meitämme parhaalla viinalla ja voiteella, älkäämme unhoittako kevätkukkasia;"],[2,8,"Kantakaamme seppeleitä nuotista kukkasista, ennenkuin ne lakastuvat.","Kantakaamme seppeleitä nuotista kukkasista, ennenkuin ne lakastuvat."],[2,9,"Älköön yksikään olko osatoin meidän röyhkeydestämme, että joka paikassa kuulla saatasiin, kuinka me olemme iloiset olleet; sillä ei tämä tästä muuta ole kuin tämä.","Älköön yksikään olko osatoin meidän röyhkeydestämme, että joka paikassa kuulla saatasiin, kuinka me olemme iloiset olleet; sillä ei tämä tästä muuta ole kuin tämä."],[2,10,"Ahdistakaamme köyhää vanhurskasta ja älkäämme säästäkö leskiä eli ijällistä miestä, älkäämme lukua pitäkö vanhain harmaapäiden nuhtelemisesta.","Ahdistakaamme köyhää vanhurskasta ja älkäämme säästäkö leskiä eli ijällistä miestä, älkäämme lukua pitäkö vanhain harmaapäiden nuhtelemisesta."],[2,11,"Kaikki, mitä me tehdä taidamme, pitää oikein oleman; silla joka ei taida tehdä, mitä hänen mielessänsä on, ei hän mitään maksa.","Kaikki, mitä me tehdä taidamme, pitää oikein oleman; silla joka ei taida tehdä, mitä hänen mielessänsä on, ei hän mitään maksa."],[2,12,"Väijykäämme vanhurskasta, sillä hän tekee meille paljon vaivaa, ja asettaa itsensä meidän töitämme vastaan, ja nuhtelee meitä, että me syntiä teimme lakia vastaan, ja soimaa meidän menomme synniksi.","Väijykäämme vanhurskasta, sillä hän tekee meille paljon vaivaa, ja asettaa itsensä meidän töitämme vastaan, ja nuhtelee meitä, että me syntiä teimme lakia vastaan, ja soimaa meidän menomme synniksi."],[2,13,"Hän sanoo tuntevansa Jumalan, ja kehuu, että hän on Jumalan poika.","Hän sanoo tuntevansa Jumalan, ja kehuu, että hän on Jumalan poika."],[2,14,"Ja nuhtelee, mitä meidän sydämessämme on.","Ja nuhtelee, mitä meidän sydämessämme on."],[2,15,"Työläästi me voimme hänen nähdä; silla ei hänen elämänsä sovi muiden kanssa, ja hänen menonsa on peräti vastahakoinen.","Työläästi me voimme hänen nähdä; silla ei hänen elämänsä sovi muiden kanssa, ja hänen menonsa on peräti vastahakoinen."],[2,16,"Hän pitää meitä tyhminä, ja välttää teitämme niinkuin saastasuutta, ja sanoo vanhurskaille viimein hyvin käyvän, ja kehuu, että Jumala on hänen isänsä.","Hän pitää meitä tyhminä, ja välttää teitämme niinkuin saastasuutta, ja sanoo vanhurskaille viimein hyvin käyvän, ja kehuu, että Jumala on hänen isänsä."],[2,17,"Niin katsokaamme siis, jos hänen sanansa ovat todet, ja koetelkaamme, mikä loppu hänellä on.","Niin katsokaamme siis, jos hänen sanansa ovat todet, ja koetelkaamme, mikä loppu hänellä on."],[2,18,"Jos hän on totinen Jumalan poika, niin hän häntä auttaa, ja vapahtaa hänen vainomiesten käsistä.","Jos hän on totinen Jumalan poika, niin hän häntä auttaa, ja vapahtaa hänen vainomiesten käsistä."],[2,19,"Häpiällä ja pilkalla me kidutamme häntä, että me näkisimme, kuinka jumalinen hän on ja ymmärtäisimme, kuinka kärsivällinen hän on.","Häpiällä ja pilkalla me kidutamme häntä, että me näkisimme, kuinka jumalinen hän on ja ymmärtäisimme, kuinka kärsivällinen hän on."],[2,20,"Me tahdomme häntä tuomita häpiälliseen kuolemaan; silloinhan tunnetaan sanoistansa.","Me tahdomme häntä tuomita häpiälliseen kuolemaan; silloinhan tunnetaan sanoistansa."],[2,21,"Senkaltaista he aikovat ja menevät väärin; heidän pahuutensa on heidät sokiaksi tehnyt.","Senkaltaista he aikovat ja menevät väärin; heidän pahuutensa on heidät sokiaksi tehnyt."],[2,22,"Ja ei he tunne Jumalan salaisia neuvoja, eikä ole toivoneet, että pyhä elämä pitää palkan saaman, ja katsovat ylön sen kunnian, jonka pyhäin sielut saaman pitää.","Ja ei he tunne Jumalan salaisia neuvoja, eikä ole toivoneet, että pyhä elämä pitää palkan saaman, ja katsovat ylön sen kunnian, jonka pyhäin sielut saaman pitää."],[2,23,"Sillä Jumala on luonut ihmisen ijankaikkiseen elämään; ja on hänen luonut kaltaiseksensa.","Sillä Jumala on luonut ihmisen ijankaikkiseen elämään; ja on hänen luonut kaltaiseksensa."],[2,24,"Mutta perkeleen kateudesta on kuolema maailmaan tullut, ja ne, jotka hänen puoltansa pitävät, auttavat myös itsensä siihen.","Mutta perkeleen kateudesta on kuolema maailmaan tullut, ja ne, jotka hänen puoltansa pitävät, auttavat myös itsensä siihen."],[3,1,"Mutta vanhurskasten sielut ovat Jumalan kädessä, ja ei kuoleman vaiva lähesty heitä.","Mutta vanhurskasten sielut ovat Jumalan kädessä, ja ei kuoleman vaiva lähesty heitä."],[3,2,"Taitamattomain mielestä näkyvät he kuolevan, jä heidän lähdentönsä luetaan kivuksi,","Taitamattomain mielestä näkyvät he kuolevan, jä heidän lähdentönsä luetaan kivuksi,"],[3,3,"Ja heidän loppunsa kadotukseksi; mutta he ovat rauhassa.","Ja heidän loppunsa kadotukseksi; mutta he ovat rauhassa."],[3,4,"Jos he vielä ihmisten silmäin edessä paljon kärsivät, niin on heillä kuitenkin vahva toivo, ettei heidän ikänä kuoleman pidä§.","Jos he vielä ihmisten silmäin edessä paljon kärsivät, niin on heillä kuitenkin vahva toivo, ettei heidän ikänä kuoleman pidä§."],[3,5,"He tulevat vähä vaivatuksi, mutta heille pitää paljo hyvää tapahtuman; sillä Jumala koettelee heitä§, ja löytää heidät mahdolliseksi itsellensä.","He tulevat vähä vaivatuksi, mutta heille pitää paljo hyvää tapahtuman; sillä Jumala koettelee heitä§, ja löytää heidät mahdolliseksi itsellensä."],[3,6,"Hän koettelee heitä niinkuin kulta ahjossa, ja ottaa heitä vastaan niinkuin täydellisen uhrin.","Hän koettelee heitä niinkuin kulta ahjossa, ja ottaa heitä vastaan niinkuin täydellisen uhrin."],[3,7,"Ja siihen aikaan kuin Jumala katsoo sitä, niin he kirkkaasti paistavat, ja menevät niinkuin kipinät orsissa.","Ja siihen aikaan kuin Jumala katsoo sitä, niin he kirkkaasti paistavat, ja menevät niinkuin kipinät orsissa."],[3,8,"Heidän pitää tuomitseman pakanoita, ja hallitseman kansoja; ja Herra hallitsee heitä ijankaikkisesti.","Heidän pitää tuomitseman pakanoita, ja hallitseman kansoja; ja Herra hallitsee heitä ijankaikkisesti."],[3,9,"Sillä jotka häneen turvaavat, ymmärtävät totuuden, ja jotka lujat ovat rakkaudessa, ei pidä hänestä luovutettaman. Sillä hänen pyhänsä ovat armossa ja laupiudessa, ja hän katsoo valituitansa.","Sillä jotka häneen turvaavat, ymmärtävät totuuden, ja jotka lujat ovat rakkaudessa, ei pidä hänestä luovutettaman. Sillä hänen pyhänsä ovat armossa ja laupiudessa, ja hän katsoo valituitansa."],[3,10,"Mutta jumalattomat rangaistaan niinkuin he pelkäsivätkin; silla ei he vanhurskaasta lukua pitäneet, ja luopuivat Herrasta.","Mutta jumalattomat rangaistaan niinkuin he pelkäsivätkin; silla ei he vanhurskaasta lukua pitäneet, ja luopuivat Herrasta."],[3,11,"Sillä joka viisauden ja kurituksen katsoo ylön, se on onneton, ja heidän toivonsa on tyhjä, heidän työnsä turha, ja heidän tekonsa hedelmätöin.","Sillä joka viisauden ja kurituksen katsoo ylön, se on onneton, ja heidän toivonsa on tyhjä, heidän työnsä turha, ja heidän tekonsa hedelmätöin."],[3,12,"Heidän vaimonsa ovat hullut, ja heidän lapsensa pahanilkiset.","Heidän vaimonsa ovat hullut, ja heidän lapsensa pahanilkiset."],[3,13,"Kirottu on kaikki, mikä heistä on syntynyt; sillä autuas on hedelmätöin, joka on saastuttamatoin, ja ei ole ryhtynyt syntisen vuoteeseen, se hänelle silloin hyväksi tulee, kuin sielut etsitään.","Kirottu on kaikki, mikä heistä on syntynyt; sillä autuas on hedelmätöin, joka on saastuttamatoin, ja ei ole ryhtynyt syntisen vuoteeseen, se hänelle silloin hyväksi tulee, kuin sielut etsitään."],[3,14,"Niin myös hedelmätöin, joka ei vääryyttä tee kädellänsä, eikä mitään pahaa ajattele Herraa vastaan; hänelle annetaan uskonsa edestä erinomainen lahja, ja parempi osa Herran templissä.","Niin myös hedelmätöin, joka ei vääryyttä tee kädellänsä, eikä mitään pahaa ajattele Herraa vastaan; hänelle annetaan uskonsa edestä erinomainen lahja, ja parempi osa Herran templissä."],[3,15,"Sillä hyvä työ antaa hyvän palkan, ja ymmärryksen juuri ei häviä.","Sillä hyvä työ antaa hyvän palkan, ja ymmärryksen juuri ei häviä."],[3,16,"Mutta äpärät ei pidä menestymän, ja salavuoteisen siemenen pitää hukkuman.","Mutta äpärät ei pidä menestymän, ja salavuoteisen siemenen pitää hukkuman."],[3,17,"Ja jos he vielä kauvan elävät, niin täytyy heidän kuitenkin viimein häpiään tulla, ja heidän ikänsä pitää kuitenkin lopulla ilman kunniaa oleman.","Ja jos he vielä kauvan elävät, niin täytyy heidän kuitenkin viimein häpiään tulla, ja heidän ikänsä pitää kuitenkin lopulla ilman kunniaa oleman."],[3,18,"Jos he varhain kuolevat, niin ei heillä ole toivoa, eli lohdutusta tuomiopäivänä.","Jos he varhain kuolevat, niin ei heillä ole toivoa, eli lohdutusta tuomiopäivänä."],[3,19,"Sillä jumalattomat saavat pahan lopun.","Sillä jumalattomat saavat pahan lopun."],[4,1,"Parempi on lapsetonna olla puhtaudessa; sillä sille on loppumaton ylistys, ja siitä Jumala ja ihmiset paljon pitävät.","Parempi on lapsetonna olla puhtaudessa; sillä sille on loppumaton ylistys, ja siitä Jumala ja ihmiset paljon pitävät."],[4,2,"Kussa se on, sitä seurataan, kussa ei se ole, niin sitä kaivataan; ja siitä koreillaan ijankaikkisella kaunistuksella ja saadaan voitto puhtauden kilvoittelemisella.","Kussa se on, sitä seurataan, kussa ei se ole, niin sitä kaivataan; ja siitä koreillaan ijankaikkisella kaunistuksella ja saadaan voitto puhtauden kilvoittelemisella."],[4,3,"Mutta jumalattomain suuri hedelmällinen joukko on kelvotoin,ja mitä huoruudessa istutetaan, ei se syvältä juurru, eikä vahvasti perusteta.","Mutta jumalattomain suuri hedelmällinen joukko on kelvotoin,ja mitä huoruudessa istutetaan, ei se syvältä juurru, eikä vahvasti perusteta."],[4,4,"Jos he hetken aikaa oksissa vihoittavat, niin he liikutetaan tuulelta; ja että he ovat valtoimet, niin he tulevat myrskyltä hävitetyksi.","Jos he hetken aikaa oksissa vihoittavat, niin he liikutetaan tuulelta; ja että he ovat valtoimet, niin he tulevat myrskyltä hävitetyksi."],[4,5,"Hyötyvesat murtuvat, ja heidän hedelmänsä on kelvotoin, jäävät röhkäleeksi ja ei kelpaa syödä;","Hyötyvesat murtuvat, ja heidän hedelmänsä on kelvotoin, jäävät röhkäleeksi ja ei kelpaa syödä;"],[4,6,"Sillä ne lapset, jotka ei aviovuoteesta synnytetä, tunnustavat vanhempainsa pahuuden, kuin heiltä kysytään. 3: 16.","Sillä ne lapset, jotka ei aviovuoteesta synnytetä, tunnustavat vanhempainsa pahuuden, kuin heiltä kysytään. 3: 16."],[4,7,"Mutta jos vanhurskas varhain kuolee, hän hän on kuitenkin levossa.","Mutta jos vanhurskas varhain kuolee, hän hän on kuitenkin levossa."],[4,8,"Sillä ei ikä siitä kunniallinen ole, että hän kauvan elää, ja hänellä on monta vuotta;","Sillä ei ikä siitä kunniallinen ole, että hän kauvan elää, ja hänellä on monta vuotta;"],[4,9,"Vaan toimi ihmisten seassa ovat oikiat harmaat karvat, ja virheetöin elämä on oikia vanha ikä.","Vaan toimi ihmisten seassa ovat oikiat harmaat karvat, ja virheetöin elämä on oikia vanha ikä."],[4,10,"Sillä hän kelpasi Jumalalle ja on hänelle rakas.","Sillä hän kelpasi Jumalalle ja on hänelle rakas."],[4,11,"Hän on oteltu pois elämästä syntisten seasta, ja on temmattu pois, ettei pahuus hänen ymmärrystänsä kääntäisi, eli väärä oppi hänen sieluansa viettelisit.","Hän on oteltu pois elämästä syntisten seasta, ja on temmattu pois, ettei pahuus hänen ymmärrystänsä kääntäisi, eli väärä oppi hänen sieluansa viettelisit."],[4,12,"Sillä paha tapa turmelee hyvät, ja paha himo kääntää viattoman sydämen.","Sillä paha tapa turmelee hyvät, ja paha himo kääntää viattoman sydämen."],[4,13,"Hän on nopiasti täydelliseksi tullut, ja on täyttänyt monta vuotta.","Hän on nopiasti täydelliseksi tullut, ja on täyttänyt monta vuotta."],[4,14,"Sillä hänen sielunsa kelpasi Jumalalle: sen tähden kiiruhti hän hänen pois tästä pahasta elämästä.","Sillä hänen sielunsa kelpasi Jumalalle: sen tähden kiiruhti hän hänen pois tästä pahasta elämästä."],[4,15,"Mutta ihmiset, jotka sen näkevät, ei siitä lukua pidä, eikä sitä sydämeensä pane, että Jumalan pyhät armossa ja laupiudessa ovat, ja että hän katsoo valittujensa puoleen.","Mutta ihmiset, jotka sen näkevät, ei siitä lukua pidä, eikä sitä sydämeensä pane, että Jumalan pyhät armossa ja laupiudessa ovat, ja että hän katsoo valittujensa puoleen."],[4,16,"Sillä kuollut vanhurskas tuomitsee eläviä jumalattomia, ja nuori, joka pian täydelliseksi tullut on, tuomitsee vääräin pitkän elämän.","Sillä kuollut vanhurskas tuomitsee eläviä jumalattomia, ja nuori, joka pian täydelliseksi tullut on, tuomitsee vääräin pitkän elämän."],[4,17,"He näkevät kyllä viisaan lopun, mutta ei he tiedä, mitä Herra hänestä ajattelee, ja minkätähden hän häntä varjelee.","He näkevät kyllä viisaan lopun, mutta ei he tiedä, mitä Herra hänestä ajattelee, ja minkätähden hän häntä varjelee."],[4,18,"He kyllä sen näkevät, ja ei pidä lukua: mutta Herra nauraa heitä.","He kyllä sen näkevät, ja ei pidä lukua: mutta Herra nauraa heitä."],[4,19,"Ja heidän pitää sentähden häpiällä lankeeman, ja oleman häväistys kuolleiden seassa ijankaikkisesti; ja hän kukistaa heitä maahan tapaturmaisesti, ja repii heitä pois perustukseen asti, että he peräti hävitetään.","Ja heidän pitää sentähden häpiällä lankeeman, ja oleman häväistys kuolleiden seassa ijankaikkisesti; ja hän kukistaa heitä maahan tapaturmaisesti, ja repii heitä pois perustukseen asti, että he peräti hävitetään."],[4,20,"Heidän pitää oleman ahdistuksessa, ja heidän muistonsa pitää hukkuman, mutta heidän pitää tuleman epäileväiseksi syntinsä tunnustuksessa, ja heidän syntinsä pitää heitä nuhteleman vastoin heidän silmiänsä.","Heidän pitää oleman ahdistuksessa, ja heidän muistonsa pitää hukkuman, mutta heidän pitää tuleman epäileväiseksi syntinsä tunnustuksessa, ja heidän syntinsä pitää heitä nuhteleman vastoin heidän silmiänsä."],[5,1,"Silloin vanhurskas seisoo suurella rohkeudella niitä vastaan, jotka häntä ahdistaneet ja hänen työnsä hyljänneet ovat;","Silloin vanhurskas seisoo suurella rohkeudella niitä vastaan, jotka häntä ahdistaneet ja hänen työnsä hyljänneet ovat;"],[5,2,"Koska he sen näkevät, niin he hämmästyvät sangen hirmuisesti, ja tyhmistyvät sitä autuutta. jota ei he toivoneet.","Koska he sen näkevät, niin he hämmästyvät sangen hirmuisesti, ja tyhmistyvät sitä autuutta. jota ei he toivoneet."],[5,3,"Puhuvat toinen toisellensa, ja katuvat, ja huokaavat henkensä ahdistuksesta, ja sanovat: tämä on se, jonka me ennen pidimme nauruna ja pilkka-sananlaskuna.","Puhuvat toinen toisellensa, ja katuvat, ja huokaavat henkensä ahdistuksesta, ja sanovat: tämä on se, jonka me ennen pidimme nauruna ja pilkka-sananlaskuna."],[5,4,"Me hullut pidimme hänen elämänsä tyhmänä ja hänen loppunsa häpiänä.","Me hullut pidimme hänen elämänsä tyhmänä ja hänen loppunsa häpiänä."],[5,5,"Kuinka hän nyt on luettu Jumalan lasten sekaan, ja hänen perintönsä pyhäin sekaan'?","Kuinka hän nyt on luettu Jumalan lasten sekaan, ja hänen perintönsä pyhäin sekaan'?"],[5,6,"Sen tähden olemme eksyneet oikialta tieltä, ja vanhurskauden kynttilä ei ole meitä valistanut, eikä vanhurskauden aurinko meille koittanut.","Sen tähden olemme eksyneet oikialta tieltä, ja vanhurskauden kynttilä ei ole meitä valistanut, eikä vanhurskauden aurinko meille koittanut."],[5,7,"Me olemme kaikki käyneet vääriä ja vahingollisia teitä, ja olemme vaeltaneet harhoja retkiä; mutta Herran teitä emme ole tietäneet;","Me olemme kaikki käyneet vääriä ja vahingollisia teitä, ja olemme vaeltaneet harhoja retkiä; mutta Herran teitä emme ole tietäneet;"],[5,8,"Mitä autti meitä koreutemme? mitä hyödytti meitä rikkaus ja ylpeys?","Mitä autti meitä koreutemme? mitä hyödytti meitä rikkaus ja ylpeys?"],[5,9,"Kaikki ovat menneet ohitse niinkuin varjo, ja niinkuin sanansaattaja, joka juosten menee;","Kaikki ovat menneet ohitse niinkuin varjo, ja niinkuin sanansaattaja, joka juosten menee;"],[5,10,"Niinkuin laiva, joka aalloissa juoksee, jonka jälkeä ja vanaa, sittekuin se on mennyt ohitse, ei löydetä aalloissa;","Niinkuin laiva, joka aalloissa juoksee, jonka jälkeä ja vanaa, sittekuin se on mennyt ohitse, ei löydetä aalloissa;"],[5,11,"Eli niinkuin lintu, joka tuulessa lentää, jonka rataa ei enään löydetä, sillä hän laukuilee ja pieksää tuulta, ajaa ja eroittaa sitä liehuvaisilla siivillänsä, ja sitte ei löydetä merkkiä senkaltaisesta lennosta;","Eli niinkuin lintu, joka tuulessa lentää, jonka rataa ei enään löydetä, sillä hän laukuilee ja pieksää tuulta, ajaa ja eroittaa sitä liehuvaisilla siivillänsä, ja sitte ei löydetä merkkiä senkaltaisesta lennosta;"],[5,12,"Eli niinkuin nuoli, joka jotakuta kohden lasketaan, hajoittaa tuulen, joka kohta kokoontuu jälleen, ettei tuta taideta, kusta se mennyt on:","Eli niinkuin nuoli, joka jotakuta kohden lasketaan, hajoittaa tuulen, joka kohta kokoontuu jälleen, ettei tuta taideta, kusta se mennyt on:"],[5,13,"Niin myös me, kohta kuin me syntyneet olimme, saimme lopun, ja emme mitään hyvää työtä ole tehneet,","Niin myös me, kohta kuin me syntyneet olimme, saimme lopun, ja emme mitään hyvää työtä ole tehneet,"],[5,14,"Vaan me olemme kulutetut meidän pahuudessamme.","Vaan me olemme kulutetut meidän pahuudessamme."],[5,15,"Sillä jumalattoman toivo on kuin tomut tuulelta hajoitettu, ja niinkuin vetelä vaahto, joka myrskyltä on ajettu, ja niinkuin savu, joka tuulelta on puhallettu pois, ja niinkuin se kohta unhotetaan, joka ainoastaan päivän vieraana on ollut.","Sillä jumalattoman toivo on kuin tomut tuulelta hajoitettu, ja niinkuin vetelä vaahto, joka myrskyltä on ajettu, ja niinkuin savu, joka tuulelta on puhallettu pois, ja niinkuin se kohta unhotetaan, joka ainoastaan päivän vieraana on ollut."],[5,16,"Mutta vanhurskaat elävät ijankaikkisesti, ja Herrassa on heidän palkkansa, ja kaikkein Korkein pitää heistä murheen.","Mutta vanhurskaat elävät ijankaikkisesti, ja Herrassa on heidän palkkansa, ja kaikkein Korkein pitää heistä murheen."],[5,17,"Sentähden saavat he Kunniallisen valtakunnan ja kauniin kruunun Herran kädestä; sillä hän varjelee heitä oikialla kädellänsä, ja suojelee heitä käsivarrellansa.","Sentähden saavat he Kunniallisen valtakunnan ja kauniin kruunun Herran kädestä; sillä hän varjelee heitä oikialla kädellänsä, ja suojelee heitä käsivarrellansa."],[5,18,"Hän ottaa kiivautensa haarniskaksi, ja varustaa luontokappaleen vihollisten kostoksi.","Hän ottaa kiivautensa haarniskaksi, ja varustaa luontokappaleen vihollisten kostoksi."],[5,19,"Hän pukee päällensä vanhurskauden pantsariksi, ja panee ankaran tuomion kilveksi.","Hän pukee päällensä vanhurskauden pantsariksi, ja panee ankaran tuomion kilveksi."],[5,20,"Hän ottaa oikeuden voittamattomaksi turvaksi.","Hän ottaa oikeuden voittamattomaksi turvaksi."],[5,21,"Hän teroittaa julman vihansa miekaksi, maailman pitää menemän sotaan hänen kanssansa taitamattomia vastaan.","Hän teroittaa julman vihansa miekaksi, maailman pitää menemän sotaan hänen kanssansa taitamattomia vastaan."],[5,22,"Pitkäisen tulen ampuma pitää osaaman oikein, ja pitää pilvistä tuleman, niinkuin kovan jännitetyn joutsen jotakuta kohden.","Pitkäisen tulen ampuma pitää osaaman oikein, ja pitää pilvistä tuleman, niinkuin kovan jännitetyn joutsen jotakuta kohden."],[5,23,"Ja taajat rakeet, jylinän sateen vihasta lankeeman, niin pitää myös meren vedet julmistuman heidän päällensä. Ja virrat pitää suuresti kuohuman. Ja suuren myrskyn pitää puhaltaman heitä vastaan, ja lennättämän heitä niinkuin tuulispään.","Ja taajat rakeet, jylinän sateen vihasta lankeeman, niin pitää myös meren vedet julmistuman heidän päällensä. Ja virrat pitää suuresti kuohuman. Ja suuren myrskyn pitää puhaltaman heitä vastaan, ja lennättämän heitä niinkuin tuulispään."],[6,1,"Vääryys kaikki maakunnat hävittää, ja paha elämä kukistaa voimallisten istuimet.","Vääryys kaikki maakunnat hävittää, ja paha elämä kukistaa voimallisten istuimet."],[6,2,"Niin kuulkaat, te kuninkaat, ja ottakaat vaari: oppikaat, te tuomarit maan päällä.","Niin kuulkaat, te kuninkaat, ja ottakaat vaari: oppikaat, te tuomarit maan päällä."],[6,3,"Ottakaat korviinne te, jotka monta hallitsette, te jotka korotatte teitänne kansain päälle.","Ottakaat korviinne te, jotka monta hallitsette, te jotka korotatte teitänne kansain päälle."],[6,4,"Sillä teille on annettu valta Herralta, ja voima kaikkein Korkeimmalta, joka tahtoo kysyä, kuinka te hallitsette, ja koetella kuinka te asetatte.","Sillä teille on annettu valta Herralta, ja voima kaikkein Korkeimmalta, joka tahtoo kysyä, kuinka te hallitsette, ja koetella kuinka te asetatte."],[6,5,"Te olette hänen valtakuntansa virkamiehet, mutta ette tee oikein teidän virkanne töitä, ja ette pidä oikeutta, ette myöskään vaella Herran tahdon jälkeen.","Te olette hänen valtakuntansa virkamiehet, mutta ette tee oikein teidän virkanne töitä, ja ette pidä oikeutta, ette myöskään vaella Herran tahdon jälkeen."],[6,6,"Hän tulee hirmuisesti ja äkisti teidän päällenne; ja esivallan pitää kovan tuomion saaman.","Hän tulee hirmuisesti ja äkisti teidän päällenne; ja esivallan pitää kovan tuomion saaman."],[6,7,"Sillä huonoille tapahtuu armo, vaan voimalliset voimallisesti rangaistaan.","Sillä huonoille tapahtuu armo, vaan voimalliset voimallisesti rangaistaan."],[6,8,"Sillä, joka kaikkein päälle Herra on, ei hän pelkää ketään, eikä karta kenenkään voimaa; hän on tehnyt sekä pienet että suuret, ja hänellä on yhtäläinen suru kaikista.","Sillä, joka kaikkein päälle Herra on, ei hän pelkää ketään, eikä karta kenenkään voimaa; hän on tehnyt sekä pienet että suuret, ja hänellä on yhtäläinen suru kaikista."],[6,9,"Mutta voimallisesta pitää kova tuomio pidettämän.","Mutta voimallisesta pitää kova tuomio pidettämän."],[6,10,"Teille tyranneille minä puhun, että oppisitte viisautta, ja ette vilpistelisi","Teille tyranneille minä puhun, että oppisitte viisautta, ja ette vilpistelisi"],[6,11,"Sillä joka pyhän opin pyhänä pitää, hän pidetään pyhänä; ja joka hänen hyvin oppii, hän on kyllä pysyväinen.","Sillä joka pyhän opin pyhänä pitää, hän pidetään pyhänä; ja joka hänen hyvin oppii, hän on kyllä pysyväinen."],[6,12,"Niin antakaat minun puheeni teille kelvata, pyytäkäät sitä, ja antakaat opettaa teitänne.","Niin antakaat minun puheeni teille kelvata, pyytäkäät sitä, ja antakaat opettaa teitänne."],[6,13,"Sillä viisaus on ihana ja katoomatoin, ja osoittaa mieluisesti itsensä niille, jotka häntä rakastavat, ja antaa itsensä niiltä löyttää, jotka häntä etsivät.","Sillä viisaus on ihana ja katoomatoin, ja osoittaa mieluisesti itsensä niille, jotka häntä rakastavat, ja antaa itsensä niiltä löyttää, jotka häntä etsivät."],[6,14,"Hän kohtaa ja ilmoittaa itsensä niille, jotka häntä mielellänsä pyytävät.","Hän kohtaa ja ilmoittaa itsensä niille, jotka häntä mielellänsä pyytävät."],[6,15,"Joka varhain nousee häntä varten, ei se näe paljon vaivaa; hän löytää hänen oven edestä vartioitsemasta.","Joka varhain nousee häntä varten, ei se näe paljon vaivaa; hän löytää hänen oven edestä vartioitsemasta."],[6,16,"Sillä häntä pyytää, on täydellinen taito; ja joka hänen tähtensä valvoo, ei se kärsi pitkällistä murhetta.","Sillä häntä pyytää, on täydellinen taito; ja joka hänen tähtensä valvoo, ei se kärsi pitkällistä murhetta."],[6,17,"Sillä hän käy ympäri, ja etsii sitä, joka hänelle on mahdollinen, ja näyttää itsensä mielellänsä tiellä, vartioiden häntä, että hän hänen kohtais.","Sillä hän käy ympäri, ja etsii sitä, joka hänelle on mahdollinen, ja näyttää itsensä mielellänsä tiellä, vartioiden häntä, että hän hänen kohtais."],[6,18,"Sillä joka itsensä antaa mielellänsä opetettaa, siinä on viisauden alku; ja joka häntä tottelee, se antaa itsensä mielellänsä opetettaa.","Sillä joka itsensä antaa mielellänsä opetettaa, siinä on viisauden alku; ja joka häntä tottelee, se antaa itsensä mielellänsä opetettaa."],[6,19,"Joka itsensä antaa mielellänsä opetettaa, se pitää hänen käskynsä; mutta kussa käskyt pidetään, siinä on totisesti pyhä elämä.","Joka itsensä antaa mielellänsä opetettaa, se pitää hänen käskynsä; mutta kussa käskyt pidetään, siinä on totisesti pyhä elämä."],[6,20,"Mutta joka pyhää elämää pitää, se lähestyy Jumalaa.","Mutta joka pyhää elämää pitää, se lähestyy Jumalaa."],[6,21,"Joka viisautta rakastaa, sen Hän tekee herraksi.","Joka viisautta rakastaa, sen Hän tekee herraksi."],[6,22,"Jos te tyrannit tahdotte kansan kuninkaat ja ruhtinaat olla,","Jos te tyrannit tahdotte kansan kuninkaat ja ruhtinaat olla,"],[6,23,"Niin pitäkäät viisaus silmäinne edessä, että te ijankaikkisesti hallitsisitte.","Niin pitäkäät viisaus silmäinne edessä, että te ijankaikkisesti hallitsisitte."],[6,24,"Mutta mikä viisaus on, ja kusta se tulee, tahdon minä teille ilmoittaa, ja en tahdo salata teiltä salautta; mutta tahdon tutkistella luotuin alusta ja julkisesti hänen tuoda edes, ja en totuutta säästää","Mutta mikä viisaus on, ja kusta se tulee, tahdon minä teille ilmoittaa, ja en tahdo salata teiltä salautta; mutta tahdon tutkistella luotuin alusta ja julkisesti hänen tuoda edes, ja en totuutta säästää"],[6,25,"Ei minun ole mitään tekemistä myrkyllisen kateuden kanssa; sillä ei sen kaltaisella ole osaa viisaudessa. Mutta kussa monta viisasta on, siellä hyvin on maailmassa, ja toimellinen kuningas on kansan turva. Sentähden antakaat itsenne opetettaa minun sanoillani, ja sen pitää tuleman teidän hyväksenne.","Ei minun ole mitään tekemistä myrkyllisen kateuden kanssa; sillä ei sen kaltaisella ole osaa viisaudessa. Mutta kussa monta viisasta on, siellä hyvin on maailmassa, ja toimellinen kuningas on kansan turva. Sentähden antakaat itsenne opetettaa minun sanoillani, ja sen pitää tuleman teidän hyväksenne."],[7,1,"Minä myös olen kuolevainen ihminen niinkuin muutkin, syntynyt sen ihmisen suvusta, joka ensisti luotiin;","Minä myös olen kuolevainen ihminen niinkuin muutkin, syntynyt sen ihmisen suvusta, joka ensisti luotiin;"],[7,2,"Ja olen äidin kohdussa tehty lihaksi, kymmenessä kuukaudessa veressä juossut kokoon miehen siemenestä, himossa sekoitettu;","Ja olen äidin kohdussa tehty lihaksi, kymmenessä kuukaudessa veressä juossut kokoon miehen siemenestä, himossa sekoitettu;"],[7,3,"Ja olen myös, kuin minä synnyin, hengen vedon saanut yhteisestä tuulesta, ja olen pudonnut maan päälle, joka meitä kaikkia kantaa; ja on myös minunkin ensimäinen ääneni ollut itku, niinkuin kaikkein muidenkin;","Ja olen myös, kuin minä synnyin, hengen vedon saanut yhteisestä tuulesta, ja olen pudonnut maan päälle, joka meitä kaikkia kantaa; ja on myös minunkin ensimäinen ääneni ollut itku, niinkuin kaikkein muidenkin;"],[7,4,"Ja olen kasvatettu kapaloissa murheen pidolla;","Ja olen kasvatettu kapaloissa murheen pidolla;"],[7,5,"Sillä ei kuninkaallakaan ole muuta alkua syntymiseensä,","Sillä ei kuninkaallakaan ole muuta alkua syntymiseensä,"],[7,6,"Vaan kaikilla on yhtäläinen tulemus elämään ja yhtäläinen lähdentö.","Vaan kaikilla on yhtäläinen tulemus elämään ja yhtäläinen lähdentö."],[7,7,"Sentähden minä rukoilin, ja minulle annettiin ymmärrys; minä huusin, ja viisauden henki tuli minuun.","Sentähden minä rukoilin, ja minulle annettiin ymmärrys; minä huusin, ja viisauden henki tuli minuun."],[7,8,"Minä pidin hänestä enempi kuin kuninkaan valtakunnasta ja istuimesta, ja rikkauden minä pidin tyhjänä hänen suhteensa.","Minä pidin hänestä enempi kuin kuninkaan valtakunnasta ja istuimesta, ja rikkauden minä pidin tyhjänä hänen suhteensa."],[7,9,"En minä pitänyt kallista kiveä hänen vertanansa; sillä kaikki kulta on hänen suhteensa niinkuin huono hieta, ja hopia on niinkuin loka hänen ehtoonsa arvattava.","En minä pitänyt kallista kiveä hänen vertanansa; sillä kaikki kulta on hänen suhteensa niinkuin huono hieta, ja hopia on niinkuin loka hänen ehtoonsa arvattava."],[7,10,"Minä rakastin häntä enemmän kuin terveyttä ja kauneutta, ja valitsin hänen minulleni valkeudeksi; sillä se paiste, joka hänestä tulee, ei sammu.","Minä rakastin häntä enemmän kuin terveyttä ja kauneutta, ja valitsin hänen minulleni valkeudeksi; sillä se paiste, joka hänestä tulee, ei sammu."],[7,11,"Mutta kaikki hyvyys on minulle tullut hänestä, ja lukematoin rikkaus on hänen kädessänsä.","Mutta kaikki hyvyys on minulle tullut hänestä, ja lukematoin rikkaus on hänen kädessänsä."],[7,12,"Minä olin iloinen kaikissa, että viisaus kävi minun edessäni kaikissa niissä; mutta en minä tietänyt, että senkaltaiset tulivat hänestä.","Minä olin iloinen kaikissa, että viisaus kävi minun edessäni kaikissa niissä; mutta en minä tietänyt, että senkaltaiset tulivat hänestä."],[7,13,"Yksivakaisesti olen minä sen oppinut, hyvällä mielellä minä häntä jaan: hänen rikkauttansa en minä salaa; sillä hän on ihmisille ääretöin tavara.","Yksivakaisesti olen minä sen oppinut, hyvällä mielellä minä häntä jaan: hänen rikkauttansa en minä salaa; sillä hän on ihmisille ääretöin tavara."],[7,14,"Jotka häntä pitävät, tulevat Jumalan ystäviksi, ja ovat otolliset, että heille on annettu sallia itsensä opettaa.","Jotka häntä pitävät, tulevat Jumalan ystäviksi, ja ovat otolliset, että heille on annettu sallia itsensä opettaa."],[7,15,"Jumala on antanut minun viisaasti puhua, ja senkaltaisen viisauden lahjaa oikein ajatella; sillä hän johdattaa viisauden tielle ja hallitsee viisaita.","Jumala on antanut minun viisaasti puhua, ja senkaltaisen viisauden lahjaa oikein ajatella; sillä hän johdattaa viisauden tielle ja hallitsee viisaita."],[7,16,"Sillä hänen kädessänsä me olemme sekä myös meidän puheemme, niin myös kaikki toimi ja taito kaikissa asioissa.","Sillä hänen kädessänsä me olemme sekä myös meidän puheemme, niin myös kaikki toimi ja taito kaikissa asioissa."],[7,17,"Sillä hän on antanut minulle vahvan tiedon kaikissa asioissa, ettii minä tiedän, kuinka maailma on tehty, ja elementteinkin voiman,","Sillä hän on antanut minulle vahvan tiedon kaikissa asioissa, ettii minä tiedän, kuinka maailma on tehty, ja elementteinkin voiman,"],[7,18,"Ajan alun, lopun ja välin, kuinka päivä pitenee ja lyhenee, kuinka vuoden ajat muuttuvat,","Ajan alun, lopun ja välin, kuinka päivä pitenee ja lyhenee, kuinka vuoden ajat muuttuvat,"],[7,19,"Ja kuinka ajastaika kuluu, kuinka tähdet asetetut ovat.","Ja kuinka ajastaika kuluu, kuinka tähdet asetetut ovat."],[7,20,"Eläinten luonnon ja metsän petoin vihan, tuulten voiman, ja mitä ihmisten mielessä on, moninaisten ruohoin luonnon, ja juurten väen.","Eläinten luonnon ja metsän petoin vihan, tuulten voiman, ja mitä ihmisten mielessä on, moninaisten ruohoin luonnon, ja juurten väen."],[7,21,"Minä tiedän kaikki, mitä salattu ja julki on; sillä viisaus, joka kaiken taidon opettaa, on minulle sen opettanut.","Minä tiedän kaikki, mitä salattu ja julki on; sillä viisaus, joka kaiken taidon opettaa, on minulle sen opettanut."],[7,22,"Sillä hänessä on ymmärtäväinen henki, pyhä, ainoa, moninainen, terävä, nopsa, vakaa, puhdas, kirkas, hiljainen, ystävällinen, tarkka, vapaa, hyväntahtoinen,","Sillä hänessä on ymmärtäväinen henki, pyhä, ainoa, moninainen, terävä, nopsa, vakaa, puhdas, kirkas, hiljainen, ystävällinen, tarkka, vapaa, hyväntahtoinen,"],[7,23,"Suloinen, luja, vahva, surutoin, kaikkivoipa, kaikkinäkevä, joka käy kaikkein henkein lävitse, ehkä kuinka toimelliset, kirkkaat ja terävät ne olisivatkaan.","Suloinen, luja, vahva, surutoin, kaikkivoipa, kaikkinäkevä, joka käy kaikkein henkein lävitse, ehkä kuinka toimelliset, kirkkaat ja terävät ne olisivatkaan."],[7,24,"Sillä viisaus on kaikkein selvin: hän menee ja käy kaikkein lävitse, hän on aivan kirkas.","Sillä viisaus on kaikkein selvin: hän menee ja käy kaikkein lävitse, hän on aivan kirkas."],[7,25,"Sillä hän on Jumalan voiman löyhkä ja Kaikkivaltiaan kunnian paiste.","Sillä hän on Jumalan voiman löyhkä ja Kaikkivaltiaan kunnian paiste."],[7,26,"Sentähden ei taida mitään saastaista tulla hänen tykönsä; sillä hän on ijankaikkisen valkeuden valo, Jumalan vaikuttavaisen voiman saastuttamatoin peili ja hänen hyvyytensä kuva.","Sentähden ei taida mitään saastaista tulla hänen tykönsä; sillä hän on ijankaikkisen valkeuden valo, Jumalan vaikuttavaisen voiman saastuttamatoin peili ja hänen hyvyytensä kuva."],[7,27,"Hän on ainoa tekee, ja tekee kuitenkin kaikki; sillä hän pysyy sinänsä ja uudistaa kaikki, ja vaikuttaa alati (a) pyhäin sieluissa, ja hän tekee Jumalan ystäviksi ja prophetaiksi. (a) Gr. sukukunnittain","Hän on ainoa tekee, ja tekee kuitenkin kaikki; sillä hän pysyy sinänsä ja uudistaa kaikki, ja vaikuttaa alati (a) pyhäin sieluissa, ja hän tekee Jumalan ystäviksi ja prophetaiksi. (a) Gr. sukukunnittain"],[7,28,"Sillä ei Jumala rakasta ketään. jos ei pysytä viisaudessa.","Sillä ei Jumala rakasta ketään. jos ei pysytä viisaudessa."],[7,29,"Hän on jalompi aurinkoa ja kaikkia tähtiä:kuin häntä valkeuteen verrataan, niin hän on vielä parempi. sillä valkeuden täytyy yötä paeta; mutta pahuus ei voita ikänä viisautta","Hän on jalompi aurinkoa ja kaikkia tähtiä:kuin häntä valkeuteen verrataan, niin hän on vielä parempi. sillä valkeuden täytyy yötä paeta; mutta pahuus ei voita ikänä viisautta"],[8,1,"Sitä minä olen rakastanut ja etsinyt häntä hamasta minun nuoruudestani, ja ajattelin häntä ottaa morsiamekseni; sillä minä olen ruvennut rakastamaan hänen kauneuttansa.","Sitä minä olen rakastanut ja etsinyt häntä hamasta minun nuoruudestani, ja ajattelin häntä ottaa morsiamekseni; sillä minä olen ruvennut rakastamaan hänen kauneuttansa."],[8,2,"Hän on kunniallisesta suvusta; sillä hänen menonsa on Jumalan tykönä, ja kaikkein kappalten Herra rakastaa häntä.","Hän on kunniallisesta suvusta; sillä hänen menonsa on Jumalan tykönä, ja kaikkein kappalten Herra rakastaa häntä."],[8,3,"Hän on salainen neuvo Jumalan tunnossa, ja hänen työnsä valitsia.","Hän on salainen neuvo Jumalan tunnossa, ja hänen työnsä valitsia."],[8,4,"Jos rikkaus on kallis kappale elettäissä: mikä on rikkaampi viisautta, joka kaikki tekee?","Jos rikkaus on kallis kappale elettäissä: mikä on rikkaampi viisautta, joka kaikki tekee?"],[8,5,"Jos taito sen tekee: kuka on taitavampi opettaja kuin hän?","Jos taito sen tekee: kuka on taitavampi opettaja kuin hän?"],[8,6,"Jos joku rakastaa vanhurskautta, hänen työnsä ovat hyvät tavat; sillä hän opettaa raittiuden, toimen, oikeuden ja väkevyyden, jotka kaikkein tarpeellisimmat ovat ihmisten elämässä.","Jos joku rakastaa vanhurskautta, hänen työnsä ovat hyvät tavat; sillä hän opettaa raittiuden, toimen, oikeuden ja väkevyyden, jotka kaikkein tarpeellisimmat ovat ihmisten elämässä."],[8,7,"Jos joku pyytää paljon tietää, niin hän osaa sekä menneet, että tulevaiset; hän ymmärtää pimiät puheet, ja arvaa työläät tapaukset; ihmeet ja kamalat hän edellä tietää, mitä tapahtuu kullakin ajalla ja hetkellä.","Jos joku pyytää paljon tietää, niin hän osaa sekä menneet, että tulevaiset; hän ymmärtää pimiät puheet, ja arvaa työläät tapaukset; ihmeet ja kamalat hän edellä tietää, mitä tapahtuu kullakin ajalla ja hetkellä."],[8,8,"Minä olen aikonut ottaakseni häntä seuraani; sillä minä tiedän hänen minulle antavan hyvää neuvoa, ja että hän lohduttaa minua surussa ja murheessa.","Minä olen aikonut ottaakseni häntä seuraani; sillä minä tiedän hänen minulle antavan hyvää neuvoa, ja että hän lohduttaa minua surussa ja murheessa."],[8,9,"Hänen kauttansa on nuorukaisella kunnia kansan seassa ja ylistys vanhain tykönä.","Hänen kauttansa on nuorukaisella kunnia kansan seassa ja ylistys vanhain tykönä."],[8,10,"Minä löydetään ymmärtäväiseksi tuomiossa ja ihmeelliseksi voimallisten seassa.","Minä löydetään ymmärtäväiseksi tuomiossa ja ihmeelliseksi voimallisten seassa."],[8,11,"Kuin minä vaikenen, odottavat he minua, kuin minä puhun, ottavat he vaarin, ja jos minä kauvan puhun, pitävät he kätensä suunsa edessä.","Kuin minä vaikenen, odottavat he minua, kuin minä puhun, ottavat he vaarin, ja jos minä kauvan puhun, pitävät he kätensä suunsa edessä."],[8,12,"Hänen kauttansa minä saan kuolemattoman nimen, ja jätän ijäisen muiston jälkeentulevaisilleni.","Hänen kauttansa minä saan kuolemattoman nimen, ja jätän ijäisen muiston jälkeentulevaisilleni."],[8,13,"Minä hallitsen kansoja, ja pakanat tulevat minulle alamaiseksi.","Minä hallitsen kansoja, ja pakanat tulevat minulle alamaiseksi."],[8,14,"Julmat tyrannit pelkäävät, kuin he minun kuulevat; kansan seassa minä olen hyvä ja sodassa sankari.","Julmat tyrannit pelkäävät, kuin he minun kuulevat; kansan seassa minä olen hyvä ja sodassa sankari."],[8,15,"Kotia tultuani kulutan minä aikani hänen kanssansa. Sillä ei häneen suututa, eikä hänestä ole mielen karvautta, vaan ilo ja riemu.","Kotia tultuani kulutan minä aikani hänen kanssansa. Sillä ei häneen suututa, eikä hänestä ole mielen karvautta, vaan ilo ja riemu."],[8,16,"Näitä minä ajattelin, ja panin sydämeeni; sillä kuolemattomuus on viisauden ajatuksessa,","Näitä minä ajattelin, ja panin sydämeeni; sillä kuolemattomuus on viisauden ajatuksessa,"],[8,17,"Ja jotka hänen ystävyydessänsä ovat, niillä on puhdas ilo, ja ääretöin rikkaus tulee hänen kättensä töistä, ja toimi hänen puheestansa, ja hyvä ylistys hänen seurastansa ja sanoistansa: minä menin ympäri etsimään ja saattamaan häntä minun tyköni.","Ja jotka hänen ystävyydessänsä ovat, niillä on puhdas ilo, ja ääretöin rikkaus tulee hänen kättensä töistä, ja toimi hänen puheestansa, ja hyvä ylistys hänen seurastansa ja sanoistansa: minä menin ympäri etsimään ja saattamaan häntä minun tyköni."],[8,18,"Minä olin hyvänkurinen lapsi, ja sain hyvän sielun.","Minä olin hyvänkurinen lapsi, ja sain hyvän sielun."],[8,19,"Mutta kuin minä hyvin kasvatettiin, kasvoin minä saastuttamattomaksi ruumiiksi,","Mutta kuin minä hyvin kasvatettiin, kasvoin minä saastuttamattomaksi ruumiiksi,"],[8,20,"Ja minä ymmärsin, etten minä muutoin taitanut puhtaana pysyä, jollei Jumala sitä antaisi, ja se myös oli taito, tuta kenenkä armo se on; niin menin minä Herran tykö, ja rukoilin häntä, ja sanoin kaikesta sydämestäni:","Ja minä ymmärsin, etten minä muutoin taitanut puhtaana pysyä, jollei Jumala sitä antaisi, ja se myös oli taito, tuta kenenkä armo se on; niin menin minä Herran tykö, ja rukoilin häntä, ja sanoin kaikesta sydämestäni:"],[9,1,"0 minun isäini Jumala ja kaiken laupeuden Herra, sinä, joka kaikki sanallas tehnyt olet,","0 minun isäini Jumala ja kaiken laupeuden Herra, sinä, joka kaikki sanallas tehnyt olet,"],[9,2,"Ja ihmiset viisaudellas valmistanut olet, että hän hallitsis kaikki luontokappaleet, jotka sinulta luodut ovat,","Ja ihmiset viisaudellas valmistanut olet, että hän hallitsis kaikki luontokappaleet, jotka sinulta luodut ovat,"],[9,3,"Että hän maailmaa hallitsis oikeudella ja vanhurskaudella, ja tuomitsis oikealla sydämellä!","Että hän maailmaa hallitsis oikeudella ja vanhurskaudella, ja tuomitsis oikealla sydämellä!"],[9,4,"Anna minulle viisautta, joka on joka paikassa sinun istuimes ympärillä, ja älä hylkää minua sinun lastes seasta.","Anna minulle viisautta, joka on joka paikassa sinun istuimes ympärillä, ja älä hylkää minua sinun lastes seasta."],[9,5,"Sillä minä olen sinun palvelias ja sinun piikas poika, heikko ihminen, joka ei kauvan elä, jolla on vähän ymmärrystä sinun laistas ja oikeudestas.","Sillä minä olen sinun palvelias ja sinun piikas poika, heikko ihminen, joka ei kauvan elä, jolla on vähän ymmärrystä sinun laistas ja oikeudestas."],[9,6,"Ja jos joku vielä ihmisten lapsista olis täydellinen, niin ei hän mitään maksa, jos ei hänellä ole sitä viisautta, joka sinulta tulee.","Ja jos joku vielä ihmisten lapsista olis täydellinen, niin ei hän mitään maksa, jos ei hänellä ole sitä viisautta, joka sinulta tulee."],[9,7,"Sinä olet minun valinnut sinun kansas kuninkaaksi ja sinun poikais ja tytärtes tuomariksi,","Sinä olet minun valinnut sinun kansas kuninkaaksi ja sinun poikais ja tytärtes tuomariksi,"],[9,8,"Ja käskit minun rakentaa sinulles templin pyhälle vuorelles ja alttarin sinun asuinkaupunkiis, joka olis sinun pyhän tabernaklis kaltainen, jonka sinä muinen annoit valmistaa.","Ja käskit minun rakentaa sinulles templin pyhälle vuorelles ja alttarin sinun asuinkaupunkiis, joka olis sinun pyhän tabernaklis kaltainen, jonka sinä muinen annoit valmistaa."],[9,9,"Ja sinun viisautes on sinun kanssas, joka sinun tekos tietää, ja oli tykönäs, kuin sinä maailman teit, ja tietää, mikä sinulle kelpaa, ja mikä oikea on sinun käskyissäs.","Ja sinun viisautes on sinun kanssas, joka sinun tekos tietää, ja oli tykönäs, kuin sinä maailman teit, ja tietää, mikä sinulle kelpaa, ja mikä oikea on sinun käskyissäs."],[9,10,"Lähetä häntä alas pyhästä taivaastas ja kunnias istuimelta: lähetä häntä, että hän olis minun tykönäni, ja työtä tekis minun kanssani, että minä ymmärtäisin, mikä sinulle otollinen on;","Lähetä häntä alas pyhästä taivaastas ja kunnias istuimelta: lähetä häntä, että hän olis minun tykönäni, ja työtä tekis minun kanssani, että minä ymmärtäisin, mikä sinulle otollinen on;"],[9,11,"Sillä hän tietää kaikki ja ymmärtää; ja anna hänen taluttaa minua töissäni toimellisesti ja varjella minua hänen voimassansa.","Sillä hän tietää kaikki ja ymmärtää; ja anna hänen taluttaa minua töissäni toimellisesti ja varjella minua hänen voimassansa."],[9,12,"Niin minun työni tulevat sinulle otollisiksi, ja niin minä tuomitsen sinun kansaas oikein, ja tulen mahdolliseksi istumaan minun isäni istuimella.","Niin minun työni tulevat sinulle otollisiksi, ja niin minä tuomitsen sinun kansaas oikein, ja tulen mahdolliseksi istumaan minun isäni istuimella."],[9,13,"Sillä kuka ihminen tietää Jumalan neuvon? eli kuka taitaa ajatella mitä Jumala tahtoo?","Sillä kuka ihminen tietää Jumalan neuvon? eli kuka taitaa ajatella mitä Jumala tahtoo?"],[9,14,"Sillä kuolevaisen ihmisen ajatukset ovat epäileväiset, ja meidän aivoituksemme ovat huikentelevaiset.","Sillä kuolevaisen ihmisen ajatukset ovat epäileväiset, ja meidän aivoituksemme ovat huikentelevaiset."],[9,15,"Sillä kuolevainen ruumis vaivaa sielua, ja maallinen asuinsia rasittaa mieltä, joka paljon ajattelee.","Sillä kuolevainen ruumis vaivaa sielua, ja maallinen asuinsia rasittaa mieltä, joka paljon ajattelee."],[9,16,"Tuskin me osaamme maallisia, ja työläästi löydämme niitä, jotka käsillä ovat.","Tuskin me osaamme maallisia, ja työläästi löydämme niitä, jotka käsillä ovat."],[9,17,"Kuka siis tahtoo tutkia taivaallisia? kuka taitaa tietää sinun neuvos, jos et sinä anna viisautta ja lähetä Pyhää Henkeäs korkeudesta?","Kuka siis tahtoo tutkia taivaallisia? kuka taitaa tietää sinun neuvos, jos et sinä anna viisautta ja lähetä Pyhää Henkeäs korkeudesta?"],[9,18,"Ja niin niiden tiet ojentuvat, jotka ovat maan päällä, ja ihmiset oppivat, mitä sinulle on otollinen, Ja viisaudella autuaiksi tulevat.","Ja niin niiden tiet ojentuvat, jotka ovat maan päällä, ja ihmiset oppivat, mitä sinulle on otollinen, Ja viisaudella autuaiksi tulevat."],[10,1,"Viisaus suojeli hänen, joka ensisti tehtiin ja luotiin maailman isäksi, ja pelasti hänen synnistänsä,","Viisaus suojeli hänen, joka ensisti tehtiin ja luotiin maailman isäksi, ja pelasti hänen synnistänsä,"],[10,2,"Ja antoi hänelle voiman hallita kaikkia.","Ja antoi hänelle voiman hallita kaikkia."],[10,3,"Kuin jumalatoin hänestä luopui vihassansa, niin hän tuli kadotetuksi, veljensä julman murhan tähden.","Kuin jumalatoin hänestä luopui vihassansa, niin hän tuli kadotetuksi, veljensä julman murhan tähden."],[10,4,"Ja kuin maa sen syyn tähden veden paisumisella turmeltiin, autti viisaus taas ja hallitsi vanhurskasta halvalla puulla..","Ja kuin maa sen syyn tähden veden paisumisella turmeltiin, autti viisaus taas ja hallitsi vanhurskasta halvalla puulla.."],[10,5,"Kuin kaikki pakanat erhetyksessä irstaasti elivät, löysi se vanhurskaan, ja piti hänen nuhteetoinna Jumalan edessä, ja vahvisti häntä vastoin isällistä sydäntä poikaansa kohtaan.","Kuin kaikki pakanat erhetyksessä irstaasti elivät, löysi se vanhurskaan, ja piti hänen nuhteetoinna Jumalan edessä, ja vahvisti häntä vastoin isällistä sydäntä poikaansa kohtaan."],[10,6,"Se pelasti myös vanhurskaan, kuin jnmalattomat hukkuivat, kuin hän tulta pakeni, joka viiden kaupungin päälle lankesi,","Se pelasti myös vanhurskaan, kuin jnmalattomat hukkuivat, kuin hän tulta pakeni, joka viiden kaupungin päälle lankesi,"],[10,7,"Joka maa autiolla on ja vielä suitsee pahuuden todistukseksi, ja puut, jotka raakaa hedelmää kantavat, ja suolapatsas, jotka seisoo epäuskoisen sielun muistoksi.","Joka maa autiolla on ja vielä suitsee pahuuden todistukseksi, ja puut, jotka raakaa hedelmää kantavat, ja suolapatsas, jotka seisoo epäuskoisen sielun muistoksi."],[10,8,"Sillä joka ei tottele viisautta, heillä ei ole ainoasti se vahingoksi, ettei he tunne hyvää, vaan jättävät jälkeensä eläville tyhmyytensä muiston, ettei salata taideta, missä he erehtyneet ovat.","Sillä joka ei tottele viisautta, heillä ei ole ainoasti se vahingoksi, ettei he tunne hyvää, vaan jättävät jälkeensä eläville tyhmyytensä muiston, ettei salata taideta, missä he erehtyneet ovat."],[10,9,"Mutta viisaus vapahtaa heitä kaikesta tuskasta, jotka häneen turvaavat.","Mutta viisaus vapahtaa heitä kaikesta tuskasta, jotka häneen turvaavat."],[10,10,"Se johdatti myös vanhurskasta, jonka täytyi veljensä vihan tähden paeta, oikiaa tietä, ja osoitti hänelle Jumalan valtakunnan, ja antoi hänelle pyhäin tiedon; autti häntä hänen työssänsä, ja hän menestyi ja sai paljon tavaraa työllänsä;","Se johdatti myös vanhurskasta, jonka täytyi veljensä vihan tähden paeta, oikiaa tietä, ja osoitti hänelle Jumalan valtakunnan, ja antoi hänelle pyhäin tiedon; autti häntä hänen työssänsä, ja hän menestyi ja sai paljon tavaraa työllänsä;"],[10,11,"Ja oli hänen kanssansa, kuin hänelle vääryyttä tehtiin niiltä, jotka hänelle tekivät väkivaltaa, ja teki hänen rikkaaksi;","Ja oli hänen kanssansa, kuin hänelle vääryyttä tehtiin niiltä, jotka hänelle tekivät väkivaltaa, ja teki hänen rikkaaksi;"],[10,12,"Ja suojeli häntä vihamiehiltänsä, ja varjeli niiltä, jotka häntä ajoivat takaa; se antoi hänelle voiton väkevässä taistelemisessa, että hän ymmärtäis jumalisuuden olevan voimallisemman kaikkia.","Ja suojeli häntä vihamiehiltänsä, ja varjeli niiltä, jotka häntä ajoivat takaa; se antoi hänelle voiton väkevässä taistelemisessa, että hän ymmärtäis jumalisuuden olevan voimallisemman kaikkia."],[10,13,"Ei se hyljännyt vanhurskasta, kuin hän myytiin pois, vaan varjeli häntä synnistä, ja seurasi häntä vankihuoneesen;","Ei se hyljännyt vanhurskasta, kuin hän myytiin pois, vaan varjeli häntä synnistä, ja seurasi häntä vankihuoneesen;"],[10,14,"Ja ei hyljännyt häntä siteissä., siihenasti että se antoi hänen saada valtakunnan valtikan ja vallan niiden ylitse, jotka hänelle tekivät väkivaltaa: ja saatti heitä valhetteliaksi, jotka häntä laittivat, ja antoi hänelle iankaikkisen kunnian.","Ja ei hyljännyt häntä siteissä., siihenasti että se antoi hänen saada valtakunnan valtikan ja vallan niiden ylitse, jotka hänelle tekivät väkivaltaa: ja saatti heitä valhetteliaksi, jotka häntä laittivat, ja antoi hänelle iankaikkisen kunnian."],[10,15,"Se vapahti pyhän kansan ja nuhteettoman siemenen pakanoista, jotka heitä vaivasivat.","Se vapahti pyhän kansan ja nuhteettoman siemenen pakanoista, jotka heitä vaivasivat."],[10,16,"Se tuli Herran palvelian sieluun., ja seisoi julmia kuninkaita vastaan ihmeillä ja tunnustähdillä.","Se tuli Herran palvelian sieluun., ja seisoi julmia kuninkaita vastaan ihmeillä ja tunnustähdillä."],[10,17,"Se maksoi pyhille heidän työnsä palkan, ja johdatti heitä ihmeellistä tietä, ja oli heille päivällä varjelus ja yöllä liekki niin kuin tähdet","Se maksoi pyhille heidän työnsä palkan, ja johdatti heitä ihmeellistä tietä, ja oli heille päivällä varjelus ja yöllä liekki niin kuin tähdet"],[10,18,"Hän vei heitä Punaisen meren lävitse, talutti heitä suurten vetten keskeltä.","Hän vei heitä Punaisen meren lävitse, talutti heitä suurten vetten keskeltä."],[10,19,"Mutta heidän vihollisensa hän upotti ja nämät hän veti syvyyden pohjasta.","Mutta heidän vihollisensa hän upotti ja nämät hän veti syvyyden pohjasta."],[10,20,"Sentähden ottivat vanhurskaat saaliin jumalattomilta, ja ylistivät. sinun pyhää nimeäs, Herra, ja kiittivät yksimielisesti sinun voitollista kättäs.","Sentähden ottivat vanhurskaat saaliin jumalattomilta, ja ylistivät. sinun pyhää nimeäs, Herra, ja kiittivät yksimielisesti sinun voitollista kättäs."],[10,21,"Sillä viisaus avasi mykkäin suun ja teki lasten kielet puhumaan.","Sillä viisaus avasi mykkäin suun ja teki lasten kielet puhumaan."],[11,1,"Se antoi menestyä heidän tekonsa pyhän prophetan käden kautta,","Se antoi menestyä heidän tekonsa pyhän prophetan käden kautta,"],[11,2,"Ja johdatti heitä synkän korven lävitse, niin että he majansa rakensivat korpeen,","Ja johdatti heitä synkän korven lävitse, niin että he majansa rakensivat korpeen,"],[11,3,"Ja seisoivat vihollisiansa vastaan, ja kostivat vihamiehillensä.","Ja seisoivat vihollisiansa vastaan, ja kostivat vihamiehillensä."],[11,4,"Kuin he janosivat, rukoilivat he sinua, Ja heille annettiin vettä korkiasta vuoresta, ja he sammuttivat janonsa kovasta kivestä.","Kuin he janosivat, rukoilivat he sinua, Ja heille annettiin vettä korkiasta vuoresta, ja he sammuttivat janonsa kovasta kivestä."],[11,5,"Ja jolla heidän vihamiehensä vaivattiin,","Ja jolla heidän vihamiehensä vaivattiin,"],[11,6,"Se tuli heille hyväksi, kuin he hätää kärsivät.","Se tuli heille hyväksi, kuin he hätää kärsivät."],[11,7,"Sillä niinkuin he hämmästyivät verta, joka tuli vuotavan veden siaan, käskyn rangaistukseksi, että lapsia tapettaman piti,","Sillä niinkuin he hämmästyivät verta, joka tuli vuotavan veden siaan, käskyn rangaistukseksi, että lapsia tapettaman piti,"],[11,8,"Niin sinä annoit näille vettä yltäkylläisesti tietämättä,","Niin sinä annoit näille vettä yltäkylläisesti tietämättä,"],[11,9,"Ja annoit silloin nähdä heidän janostansa, kuinka sinä vihollisia vaivasit.","Ja annoit silloin nähdä heidän janostansa, kuinka sinä vihollisia vaivasit."],[11,10,"Sillä koska nämät kiusattiin ja armolla kuritettiin, ymmärsivät he, kuinka jumalattomat vihassa tuomittiin ja rangaistiin.","Sillä koska nämät kiusattiin ja armolla kuritettiin, ymmärsivät he, kuinka jumalattomat vihassa tuomittiin ja rangaistiin."],[11,11,"Näitä sinä olet niinkuin isä neuvonut ja koetellut; mutta niitä muita niinkuin ankara kuningas rangaissut ja tuominnut,","Näitä sinä olet niinkuin isä neuvonut ja koetellut; mutta niitä muita niinkuin ankara kuningas rangaissut ja tuominnut,"],[11,12,"Ja tulivat rangaistuksi, sekä ne, jotka läsnä, että ne, jotka taampana olivat.","Ja tulivat rangaistuksi, sekä ne, jotka läsnä, että ne, jotka taampana olivat."],[11,13,"Sillä heille tuli kaksinkertainen murhe ja huokaus, kuin he ajattelivat niitä, mitkä edes menneet olivat.","Sillä heille tuli kaksinkertainen murhe ja huokaus, kuin he ajattelivat niitä, mitkä edes menneet olivat."],[11,14,"Sillä koska he kuulivat heillensä hyväksi tapahtuvan sen, kuin heitä vaivattiin, tunsivat he Herran.","Sillä koska he kuulivat heillensä hyväksi tapahtuvan sen, kuin heitä vaivattiin, tunsivat he Herran."],[11,15,"Sillä joita he ennen ajoivat pois ylönkatseesta, hylkäsivät ja pilkkasivat, niitä täytyi heidän viimein ihmetellä, koska niin tapahtui, ettei heidän janonsa ollut niinkuin vanhurskasten.","Sillä joita he ennen ajoivat pois ylönkatseesta, hylkäsivät ja pilkkasivat, niitä täytyi heidän viimein ihmetellä, koska niin tapahtui, ettei heidän janonsa ollut niinkuin vanhurskasten."],[11,16,"Niin myös heidän väärän menonsa tyhmäin ajatusten tähden, jonka kautta he niin petetyksi tulivat, että he rukoilivat järjettömiä matoja ja ylönkatsotuita petoja, lähetit sinä heidän sekaansa suuren joukon metsän petoja rangaistukseksi:","Niin myös heidän väärän menonsa tyhmäin ajatusten tähden, jonka kautta he niin petetyksi tulivat, että he rukoilivat järjettömiä matoja ja ylönkatsotuita petoja, lähetit sinä heidän sekaansa suuren joukon metsän petoja rangaistukseksi:"],[11,17,"Että he ymmärtäisivät, että millä joku syntiä tekee, sillä hän myös vaivataan.","Että he ymmärtäisivät, että millä joku syntiä tekee, sillä hän myös vaivataan."],[11,18,"Sillä sinun kaikkivaltiaalle kädelles, jolla sinä maailman valmistamattomasta aineesta luonut olet, ei ollut mahdotoin, lähettää heidän päällensä karhujoukkoja ja rohkeita jalopeuroja,","Sillä sinun kaikkivaltiaalle kädelles, jolla sinä maailman valmistamattomasta aineesta luonut olet, ei ollut mahdotoin, lähettää heidän päällensä karhujoukkoja ja rohkeita jalopeuroja,"],[11,19,"Eli vastuudesta luoda julmia ja tuntemattomia petoja, taikka niitä, jotka tulta sylkivät, taikka jotka julman savun puhalsivat, taikka jotka hirmuisia kipeniä silmistänsä laskivat,","Eli vastuudesta luoda julmia ja tuntemattomia petoja, taikka niitä, jotka tulta sylkivät, taikka jotka julman savun puhalsivat, taikka jotka hirmuisia kipeniä silmistänsä laskivat,"],[11,20,"Jotka ei ainoastaan olisi haavoittamisella heitä hukuttaa taitaneet, mutta myös hirmuisella katsannollansa heitä tappaa.","Jotka ei ainoastaan olisi haavoittamisella heitä hukuttaa taitaneet, mutta myös hirmuisella katsannollansa heitä tappaa."],[11,21,"Ja he olisivat taitaneet paitsi sitä langeta yhdellä puhalluksella koston vainosta, ja sinun voimas hengellä hukkua.","Ja he olisivat taitaneet paitsi sitä langeta yhdellä puhalluksella koston vainosta, ja sinun voimas hengellä hukkua."],[11,22,"Mutta sinä olet kaikki asettanut mitalla, luvulla ja painolla. Sillä suuri voima on aina sinussa; ja kuka voi olla sinun käsivartes väkevyyttä vastaan?","Mutta sinä olet kaikki asettanut mitalla, luvulla ja painolla. Sillä suuri voima on aina sinussa; ja kuka voi olla sinun käsivartes väkevyyttä vastaan?"],[11,23,"Sillä koko maailma on sinun edessäs niinkuin vaa'an kieli ja niinkuin aamukasteen pisara joka putoo maan päälle.","Sillä koko maailma on sinun edessäs niinkuin vaa'an kieli ja niinkuin aamukasteen pisara joka putoo maan päälle."],[11,24,"Mutta sinä armahdat kaikkia; sillä sinulla on voima kaikkein ylitse, ja kärsit ihmisten syntiä, että he itsensä parantaisivat.","Mutta sinä armahdat kaikkia; sillä sinulla on voima kaikkein ylitse, ja kärsit ihmisten syntiä, että he itsensä parantaisivat."],[11,25,"Sillä sinä rakastat kaikkia, kuin on, ja et vihaa, mitäs tehnyt olet; sillä et sinä ole mitään valmistanut, jota sinä vihata taitaisit.","Sillä sinä rakastat kaikkia, kuin on, ja et vihaa, mitäs tehnyt olet; sillä et sinä ole mitään valmistanut, jota sinä vihata taitaisit."],[11,26,"Kuinka taitaa mitään olla, jota et sinä tahtoisi? eli kuinka se taitais pysyä, jota et sinä kutsunut ole? Mutta sinä säästät kaikkia; sillä ne ovat sinun, Herra, sinä joka elämää rakastat.","Kuinka taitaa mitään olla, jota et sinä tahtoisi? eli kuinka se taitais pysyä, jota et sinä kutsunut ole? Mutta sinä säästät kaikkia; sillä ne ovat sinun, Herra, sinä joka elämää rakastat."],[12,1,"Ja sinun katoomatoin henkes on kaikissa.","Ja sinun katoomatoin henkes on kaikissa."],[12,2,"Sentähden sinä vitkaan rankaiset heitä, jotka lankeevat, ja neuvot heitä kurituksella, missä he syntiä tekevät, että he pahuudesta pelastettaisiin, ja uskoisivat sinun päälles, Herra.","Sentähden sinä vitkaan rankaiset heitä, jotka lankeevat, ja neuvot heitä kurituksella, missä he syntiä tekevät, että he pahuudesta pelastettaisiin, ja uskoisivat sinun päälles, Herra."],[12,3,"Sillä koska sinä olit vihainen sinun pyhän maas entisille asuville,","Sillä koska sinä olit vihainen sinun pyhän maas entisille asuville,"],[12,4,"Että he kauheita töitä tekivät noitumisella,","Että he kauheita töitä tekivät noitumisella,"],[12,5,"Tahdoit sinä meidän isäimme käsillä hävittää jumalattomat uhrin kantajat, ja jotka lapsensa haluttomasti tappoivat,","Tahdoit sinä meidän isäimme käsillä hävittää jumalattomat uhrin kantajat, ja jotka lapsensa haluttomasti tappoivat,"],[12,6,"Jotka söivät ihmisen lihaa ja joivat hirmuisesti verta, jolla he luulivat sinulle tekevänsä palveluksen; ja ne, jotka vanhemmat olivat, tappoivat ne sielut, joilla ei yhtään apua ollut,","Jotka söivät ihmisen lihaa ja joivat hirmuisesti verta, jolla he luulivat sinulle tekevänsä palveluksen; ja ne, jotka vanhemmat olivat, tappoivat ne sielut, joilla ei yhtään apua ollut,"],[12,7,"Että se maa, joka sinun edessäs kaikkein seassa jaloin oli, tulis Jumalan lasten mahdolliseksi asuinsiaksi.","Että se maa, joka sinun edessäs kaikkein seassa jaloin oli, tulis Jumalan lasten mahdolliseksi asuinsiaksi."],[12,8,"Kuitenkin säästit sinä heitä niinkuin ihmisiä, ja lähetit sinun sotajoukkos edelläjuoksiat hörhöläiset, että niiden piti heitä vähittäin hävittämän.","Kuitenkin säästit sinä heitä niinkuin ihmisiä, ja lähetit sinun sotajoukkos edelläjuoksiat hörhöläiset, että niiden piti heitä vähittäin hävittämän."],[12,9,"Ei tosin ollut sinulle mahdotoin antaa jumalattomia vanhurskasten alle sodassa, eli hukuttaa heitä hirmuisten petoin kautta, taikka kovalla sanalla kaikkia tyynni hukuttaa;","Ei tosin ollut sinulle mahdotoin antaa jumalattomia vanhurskasten alle sodassa, eli hukuttaa heitä hirmuisten petoin kautta, taikka kovalla sanalla kaikkia tyynni hukuttaa;"],[12,10,"Mutta sinä tuomitsit heitä vitkaan, ja annoit heille siaa parannukseen, vaikka sinä tiesit heidät pahansisuisiksi, ja heidän pahuutensa luonnolliseksi, ettei heidän ikänä pitänyt toista mieltä saaman;","Mutta sinä tuomitsit heitä vitkaan, ja annoit heille siaa parannukseen, vaikka sinä tiesit heidät pahansisuisiksi, ja heidän pahuutensa luonnolliseksi, ettei heidän ikänä pitänyt toista mieltä saaman;"],[12,11,"Sillä he olivat kirottu siemen alusta. Niin et sinä myös peljännyt ketään, annoit anteeksi heidän rikoksensa.","Sillä he olivat kirottu siemen alusta. Niin et sinä myös peljännyt ketään, annoit anteeksi heidän rikoksensa."],[12,12,"Sillä kuka sanoo sinulle: mitäs teet? eli kuka seisoo sinun tuomiotas vastaan? eli kuka nuhtelee sinua hukkuneiden pakanain tähden, jotka sinä luonut olet? eli kuka asettaa itsensä kostajaksi sinua vastaan jumalattomain ihmisten tähden?","Sillä kuka sanoo sinulle: mitäs teet? eli kuka seisoo sinun tuomiotas vastaan? eli kuka nuhtelee sinua hukkuneiden pakanain tähden, jotka sinä luonut olet? eli kuka asettaa itsensä kostajaksi sinua vastaan jumalattomain ihmisten tähden?"],[12,13,"Sillä paitsi sinua ei ole yhtään jumalaa, joka murheen pidät kaikista; osoittaakses, ettet tuomitse väärin.","Sillä paitsi sinua ei ole yhtään jumalaa, joka murheen pidät kaikista; osoittaakses, ettet tuomitse väärin."],[12,14,"Sillä ei kuninkaat eikä tylyt taida astua sinua vastaan, koska sinä rankaiset.","Sillä ei kuninkaat eikä tylyt taida astua sinua vastaan, koska sinä rankaiset."],[12,15,"Ettäs vanhurskas olet, niin sinä hallitset myös kaikki oikein, ja tiedät, ettei se sinun majesteetilles sovi, ettäs jonkun tuomitset, jota ei rangaistaman pidä.","Ettäs vanhurskas olet, niin sinä hallitset myös kaikki oikein, ja tiedät, ettei se sinun majesteetilles sovi, ettäs jonkun tuomitset, jota ei rangaistaman pidä."],[12,16,"Sillä sinun väkevyytes on oikeuden alku, ja ettäs kaikkia hallitset, niin sinä säästät myös kaikkia.","Sillä sinun väkevyytes on oikeuden alku, ja ettäs kaikkia hallitset, niin sinä säästät myös kaikkia."],[12,17,"Sillä sinä olet osoittanut väkevyytes heissä, jotka ei uskoneet, ettäs niin kaiketi voimallinen olit, ja osoitit itses niissä, jotka ylpiät olivat.","Sillä sinä olet osoittanut väkevyytes heissä, jotka ei uskoneet, ettäs niin kaiketi voimallinen olit, ja osoitit itses niissä, jotka ylpiät olivat."],[12,18,"Mutta sinä väkevä hallitsia tuomitset hiljaisuudessa, ja hallitset meitä paljolla kärsivällisyydellä; sillä sinä voit tehdä, mitäs tahdot.","Mutta sinä väkevä hallitsia tuomitset hiljaisuudessa, ja hallitset meitä paljolla kärsivällisyydellä; sillä sinä voit tehdä, mitäs tahdot."],[12,19,"Mutta sinä opetat kansaas senkaltaisIlla töillä, että vanhurskaana ja hyvänä oltaman pitäis; ja sinä annat sinun lapses tietää,.että he olisivat hyvässä toivossa, ettäs otat parannuksen syntien edestä.","Mutta sinä opetat kansaas senkaltaisIlla töillä, että vanhurskaana ja hyvänä oltaman pitäis; ja sinä annat sinun lapses tietää,.että he olisivat hyvässä toivossa, ettäs otat parannuksen syntien edestä."],[12,20,"Sillä jos sinä lastes viholliset ja ne, jotka kuolemaan vikapäät olivat, senkaltaisella säästämisellä ja kärsivällisyydellä rankaisit, ja annoit heille aikaa ja tilaa itsensä parantaa:","Sillä jos sinä lastes viholliset ja ne, jotka kuolemaan vikapäät olivat, senkaltaisella säästämisellä ja kärsivällisyydellä rankaisit, ja annoit heille aikaa ja tilaa itsensä parantaa:"],[12,21,"Kuinka paljoa enempi sinä olet pitkämielinen, koskas tuomitset lapsias, joiden isäin kanssa sinä valan ja liiton monesta hyvästä lupauksesta tehnyt olet.","Kuinka paljoa enempi sinä olet pitkämielinen, koskas tuomitset lapsias, joiden isäin kanssa sinä valan ja liiton monesta hyvästä lupauksesta tehnyt olet."],[12,22,"Sen tähden, niin usiasti kuin sinä meidän vihollisiamme vaivaat, teet sinä sen meille kuritukseksi, että me ottaisimme visusti vaarin sinun hyvyydestäs: jos me tuomitut olisimme, että me kuitenkin turvaisimme sinun laupiutees.","Sen tähden, niin usiasti kuin sinä meidän vihollisiamme vaivaat, teet sinä sen meille kuritukseksi, että me ottaisimme visusti vaarin sinun hyvyydestäs: jos me tuomitut olisimme, että me kuitenkin turvaisimme sinun laupiutees."],[12,23,"Sentähden sinä rankaisit jumalattomat omilla kauhistuksillansa, jotka järjetöintä elämää pitivät.","Sentähden sinä rankaisit jumalattomat omilla kauhistuksillansa, jotka järjetöintä elämää pitivät."],[12,24,"Sillä he olivat niin peräti syvälle tulleet erhetykseen, että he myös pitivät ne pedot, joita heidän vihollisensa katsoivat ylön, jumalinansa, petetyt niinkuin taitamattomat lapset.","Sillä he olivat niin peräti syvälle tulleet erhetykseen, että he myös pitivät ne pedot, joita heidän vihollisensa katsoivat ylön, jumalinansa, petetyt niinkuin taitamattomat lapset."],[12,25,"Sen tähden olet sinä myös lähettänyt heidän sekaansa häpiällisen rangaistuksen, niinkuin järjettömille lapsille.","Sen tähden olet sinä myös lähettänyt heidän sekaansa häpiällisen rangaistuksen, niinkuin järjettömille lapsille."],[12,26,"Ja koska ei he senkaltaista häpiällistä rangaistusta totelleet, tulivat he Jumalan ankaran rangaistuksen alle.","Ja koska ei he senkaltaista häpiällistä rangaistusta totelleet, tulivat he Jumalan ankaran rangaistuksen alle."],[12,27,"Sillä he vaivattiin niiltä, jotka he jumalinansa pitivät, joka heille oli suureksi ylönkatseeksi, koska he näkivät hänen, jota ei he ennen tuta tahtoneet, ja oikiaksi Jumalaksi tunnustivat; sentähden tuli kadotus viimein heidän päällensä.","Sillä he vaivattiin niiltä, jotka he jumalinansa pitivät, joka heille oli suureksi ylönkatseeksi, koska he näkivät hänen, jota ei he ennen tuta tahtoneet, ja oikiaksi Jumalaksi tunnustivat; sentähden tuli kadotus viimein heidän päällensä."],[13,1,"Kaikki ihmiset ovat luonnostansa turhat, jotka ei Jumalasta mitään tiedä ja ei tunne häntä näkyväisestä hyvyydestä, eikä katso töistä, kuka tekiä on;","Kaikki ihmiset ovat luonnostansa turhat, jotka ei Jumalasta mitään tiedä ja ei tunne häntä näkyväisestä hyvyydestä, eikä katso töistä, kuka tekiä on;"],[13,2,"Vaan pitävät taikka tulen, eli tuulen, eli puuskauksen, eli tähdet, eli väkevät vedet, auringon ja kuun taivaassa, jotka maailmaa haIlitsevat, jumalina.","Vaan pitävät taikka tulen, eli tuulen, eli puuskauksen, eli tähdet, eli väkevät vedet, auringon ja kuun taivaassa, jotka maailmaa haIlitsevat, jumalina."],[13,3,"Mutta jos heillä olis hyvä suosio niiden kauniisen muotoon, niin että he sentähden pitäisivät niitä jumalain siassa, pitäis heidän oikeutta myöten ymmärtämän, kuinka paljoa parempi se on, joka niiden Herra on; sillä se, joka kaiken kauneuden tekiä on, hän on nämät luonut.","Mutta jos heillä olis hyvä suosio niiden kauniisen muotoon, niin että he sentähden pitäisivät niitä jumalain siassa, pitäis heidän oikeutta myöten ymmärtämän, kuinka paljoa parempi se on, joka niiden Herra on; sillä se, joka kaiken kauneuden tekiä on, hän on nämät luonut."],[13,4,"Ja jos he ihmettelisivät niiden voimaa ja väkeä, pitäis heidän myös oikeudella ajatteleman, kuinka paljoa voimallisempi se on, joka kaikki nämät valmistanut on.","Ja jos he ihmettelisivät niiden voimaa ja väkeä, pitäis heidän myös oikeudella ajatteleman, kuinka paljoa voimallisempi se on, joka kaikki nämät valmistanut on."],[13,5,"Sillä senkaltaisesta suuresta kauneudesta ja luomisesta taitaa Luoja niinkuin yhdessä kuvassa tunnetuksi tulla.","Sillä senkaltaisesta suuresta kauneudesta ja luomisesta taitaa Luoja niinkuin yhdessä kuvassa tunnetuksi tulla."],[13,6,"Vaikka ei näiden ylitse niin suuresti valittamista ole; sillä he myös taitavat erehtyä, koska he etsivät Jumalaa, ja pyysivät mielellänsä häntä löytää;","Vaikka ei näiden ylitse niin suuresti valittamista ole; sillä he myös taitavat erehtyä, koska he etsivät Jumalaa, ja pyysivät mielellänsä häntä löytää;"],[13,7,"Sillä koska he katselivat hänen luontokappaleitansa ja tutkistelivat niitä, tulivat he petetyksi niiden katselemisessa, että luontokappaleet, jotka he näkivät, olivat niin ihanat;","Sillä koska he katselivat hänen luontokappaleitansa ja tutkistelivat niitä, tulivat he petetyksi niiden katselemisessa, että luontokappaleet, jotka he näkivät, olivat niin ihanat;"],[13,8,"Kuitenkin ei he sentähden ole ilman syytä.","Kuitenkin ei he sentähden ole ilman syytä."],[13,9,"Sillä jos he ovat niin paljon ymmärtäneet, että he taisivat luontokappaleen niin korkiassa arvossa pitää: miksi ei he pikemmin häntä löytäneet, joka niiden Herra on?","Sillä jos he ovat niin paljon ymmärtäneet, että he taisivat luontokappaleen niin korkiassa arvossa pitää: miksi ei he pikemmin häntä löytäneet, joka niiden Herra on?"],[13,10,"Mutta he ovat viheliäiset, ja heidän toivonsa on luettava kuolleiden sekaan, jotka sen jumalaksi kutsuvat, jonka ihmiset tehneet ovat, niinkuin kullan ja hopian, joka taitavasti valmistettu on, ja petoin kuvan, eli kelvottomat kivet, jotka vanhaan aikaan valmistetut olivat.","Mutta he ovat viheliäiset, ja heidän toivonsa on luettava kuolleiden sekaan, jotka sen jumalaksi kutsuvat, jonka ihmiset tehneet ovat, niinkuin kullan ja hopian, joka taitavasti valmistettu on, ja petoin kuvan, eli kelvottomat kivet, jotka vanhaan aikaan valmistetut olivat."],[13,11,"Niinkuin puuseppä, kuin hän työtä etsii, hakkaa puun, veistää ja silittää sen hyvin, ja siitä visua ja taitavaa työtä tekee, joka maailman tarpeissa tarvitaan;","Niinkuin puuseppä, kuin hän työtä etsii, hakkaa puun, veistää ja silittää sen hyvin, ja siitä visua ja taitavaa työtä tekee, joka maailman tarpeissa tarvitaan;"],[13,12,"Mutta sen työn lastut kokoo hän, ja keittää ruokaa syödäksensä;","Mutta sen työn lastut kokoo hän, ja keittää ruokaa syödäksensä;"],[13,13,"Vaan mitä liiaksi on, ja ei mihinkään kelpaa, kuin väärä ja oksainen on, ottaa hän ja visusti leikkaa, kuin hän joutaa, leikkaa taitavasti, ja tekee ihmisen eli jonkun järjettömän eläimen muotoiseksi,","Vaan mitä liiaksi on, ja ei mihinkään kelpaa, kuin väärä ja oksainen on, ottaa hän ja visusti leikkaa, kuin hän joutaa, leikkaa taitavasti, ja tekee ihmisen eli jonkun järjettömän eläimen muotoiseksi,"],[13,14,"Ja panee sen punaiseksi ja valkiaksi, ja maalaa kauniiksi, ja jos siinä joku virhe on, sen hän vastuudesta maalilla sivuu;","Ja panee sen punaiseksi ja valkiaksi, ja maalaa kauniiksi, ja jos siinä joku virhe on, sen hän vastuudesta maalilla sivuu;"],[13,15,"Sitte tekee hän sille kauniin huoneen, ja kiinnittää sen seinään raudalla,","Sitte tekee hän sille kauniin huoneen, ja kiinnittää sen seinään raudalla,"],[13,16,"Niin ettei se putoo, ja niin hyvin katsoo sen; sillä hän tietää hyvin, ettei se itsiänsä auttaa taida; sillä ei se muu ole kuin kuva, ja tarvitsee apua.","Niin ettei se putoo, ja niin hyvin katsoo sen; sillä hän tietää hyvin, ettei se itsiänsä auttaa taida; sillä ei se muu ole kuin kuva, ja tarvitsee apua."],[13,17,"Ja kuin hän rukoilee tavaransa, emäntänsä ja lastensa edestä, ei hän häpee puhutella sitä, jolla ei henkeä ole,","Ja kuin hän rukoilee tavaransa, emäntänsä ja lastensa edestä, ei hän häpee puhutella sitä, jolla ei henkeä ole,"],[13,18,"Ja anoo heikolta terveyttä, rukoilee kuolleelta elämää, ja pyytää häneltä apua, joka ei mitään voi,","Ja anoo heikolta terveyttä, rukoilee kuolleelta elämää, ja pyytää häneltä apua, joka ei mitään voi,"],[13,19,"Ja siltä, joka ei käydä taida, hyvää matkaa, ja että hänen askareensa, asiansa ja tekonsa menestyis, pyytää hän voimattomalta.","Ja siltä, joka ei käydä taida, hyvää matkaa, ja että hänen askareensa, asiansa ja tekonsa menestyis, pyytää hän voimattomalta."],[14,1,"Niin myös se tekee, joka tahtoo purjehtia, ja on aikonut vaeltaa julmissa aalloissa: hän rukoilee puuta, joka heikompi sitä laivaa on, jonka päällä hän vaeltaa;","Niin myös se tekee, joka tahtoo purjehtia, ja on aikonut vaeltaa julmissa aalloissa: hän rukoilee puuta, joka heikompi sitä laivaa on, jonka päällä hän vaeltaa;"],[14,2,"Sillä se on sentähden tehty, että sillä pitää ravintoa etsittämän, ja tekiä on sen taidolla valmistanut.","Sillä se on sentähden tehty, että sillä pitää ravintoa etsittämän, ja tekiä on sen taidolla valmistanut."],[14,3,"Mutta sinun edeskatsomises, oi Isä, hallitsee sitä; sillä sinä annat tien meressä ja aaltoin keskellä pelkäämättömän juoksun,","Mutta sinun edeskatsomises, oi Isä, hallitsee sitä; sillä sinä annat tien meressä ja aaltoin keskellä pelkäämättömän juoksun,"],[14,4,"Jolla osoitat, kuinka sinä kaikissa paikoissa voimallinen olet auttamaan, vaikka joku itsensä antais merelle ilman laivaa.","Jolla osoitat, kuinka sinä kaikissa paikoissa voimallinen olet auttamaan, vaikka joku itsensä antais merelle ilman laivaa."],[14,5,"Kuitenkin, ettes tahdo sitä turhana pitää, jota sinä viisaudessas luonut olet, tapahtuu se, että ihmiset uskaltavat henkensä sen kaltaisen huonon puun päälle, ja tulevat laivassa talteen, jossa he vaeltavat aaltoin lävitse.","Kuitenkin, ettes tahdo sitä turhana pitää, jota sinä viisaudessas luonut olet, tapahtuu se, että ihmiset uskaltavat henkensä sen kaltaisen huonon puun päälle, ja tulevat laivassa talteen, jossa he vaeltavat aaltoin lävitse."],[14,6,"Sillä muinen, kun uljaat sankarit hukutettiin, pakenivat ne laivaan, joilla toivo oli, että heidän piti lisäämän maailmaa jälleen, jonka sinun kätes hallitsi, he jättivät niin maailmalle siemenen jälkeensä.","Sillä muinen, kun uljaat sankarit hukutettiin, pakenivat ne laivaan, joilla toivo oli, että heidän piti lisäämän maailmaa jälleen, jonka sinun kätes hallitsi, he jättivät niin maailmalle siemenen jälkeensä."],[14,7,"Sillä se puu on siunattu, jonka kautta vanhurskas tulee.","Sillä se puu on siunattu, jonka kautta vanhurskas tulee."],[14,8,"Mutta sitä pitää kirottaman, joka käsillä valmistetaan, se myös, joka sen tekee: tämä sentähden että hän sen teki, se sentähden, että se jumalaksi kutsutaan,.kuitenkin on katoovainen kappale","Mutta sitä pitää kirottaman, joka käsillä valmistetaan, se myös, joka sen tekee: tämä sentähden että hän sen teki, se sentähden, että se jumalaksi kutsutaan,.kuitenkin on katoovainen kappale"],[14,9,"Sillä Jumala vihaa yhtäläisesti molempia, jumalatointa ja hänen jumalatointa työtänsä,","Sillä Jumala vihaa yhtäläisesti molempia, jumalatointa ja hänen jumalatointa työtänsä,"],[14,10,"Ja työ tulee tekiänsänsä vaivatuksi.,","Ja työ tulee tekiänsänsä vaivatuksi.,"],[14,11,"Seutähden myös pakanain epäjumalat kuritetaan; sillä ovat Jumalan luontokappaleista tulleet kauhistukseksi ja ihmissieluille pahennukseksi ja ymmärtämättömille paulaksi.","Seutähden myös pakanain epäjumalat kuritetaan; sillä ovat Jumalan luontokappaleista tulleet kauhistukseksi ja ihmissieluille pahennukseksi ja ymmärtämättömille paulaksi."],[14,12,"Sillä epäjumalten asetus suurin huoruus, ja heidän alkunsa, on vahingollinen pahennus maailmassa.","Sillä epäjumalten asetus suurin huoruus, ja heidän alkunsa, on vahingollinen pahennus maailmassa."],[14,13,"Sillä ei ne alusta olleet, eikä ijankaikkisesti pysy;","Sillä ei ne alusta olleet, eikä ijankaikkisesti pysy;"],[14,14,"Vaan ihmisten turhalla kunnioittamisella he ovat tulleet maailmaan, ja sentähden ajatellut ettei ihmiset saa kauan elää.","Vaan ihmisten turhalla kunnioittamisella he ovat tulleet maailmaan, ja sentähden ajatellut ettei ihmiset saa kauan elää."],[14,15,"Sillä isä, koska hän suri ja itki poikaansa, joka häneltä, varhain tuli pois, antoi hän tehdä kuvan ja rupesi pitämään hänen joka kuollut ihminen oli, jumalana, ja asetti palvelioillensa jumalanpalveluksen ja uhrin.","Sillä isä, koska hän suri ja itki poikaansa, joka häneltä, varhain tuli pois, antoi hän tehdä kuvan ja rupesi pitämään hänen joka kuollut ihminen oli, jumalana, ja asetti palvelioillensa jumalanpalveluksen ja uhrin."],[14,16,"Sitte ajankululla pidettiin senkaltainen jumalatoin tapa lakina, että myös knvaa täytyi kunnioittaa tyrannein käskystä.","Sitte ajankululla pidettiin senkaltainen jumalatoin tapa lakina, että myös knvaa täytyi kunnioittaa tyrannein käskystä."],[14,17,"Niin myös kansa, joka ei läsnä ollen saanut kunnioittaa, että he niin kaukana asuivat, antoivat tehdä sen muodon kaukaisella maalla, ja teettivät kauniit voimallisten kuningasten kuvat, että he ahkerasti olisivat heille mielennouteeksi, sekä poissa että läsnäollessa.","Niin myös kansa, joka ei läsnä ollen saanut kunnioittaa, että he niin kaukana asuivat, antoivat tehdä sen muodon kaukaisella maalla, ja teettivät kauniit voimallisten kuningasten kuvat, että he ahkerasti olisivat heille mielennouteeksi, sekä poissa että läsnäollessa."],[14,18,"Niin autti myös tekiän suuri ahkeruus vahvistamaan ymmärtämättömiä senkaltaiseen jumalanpalvelukseen.","Niin autti myös tekiän suuri ahkeruus vahvistamaan ymmärtämättömiä senkaltaiseen jumalanpalvelukseen."],[14,19,"Sillä koska joku tahtoi palvella ruhtinaan mieliksi, teki hän kuvan kaikella taidolla kaikkein kauneimmaksi.","Sillä koska joku tahtoi palvella ruhtinaan mieliksi, teki hän kuvan kaikella taidolla kaikkein kauneimmaksi."],[14,20,"Mutta kansa, joka senkaltaisella kauniilla työllä oli kehoitettu, rupesi sitä jumalana pitämään, joka vähää ennen ihmisenä kunnioitettiin.","Mutta kansa, joka senkaltaisella kauniilla työllä oli kehoitettu, rupesi sitä jumalana pitämään, joka vähää ennen ihmisenä kunnioitettiin."],[14,21,"Senkaltaisesta asiasta tuli petollisuus maailmaan, koska ihmisiä jotenkin ahdistettiin, eli he tahtoivat tehdä tyrannille jotain mielennouteeksi, antoivat he kiville ja puille senkaltaisen nimen, kuin ei pitänyt.","Senkaltaisesta asiasta tuli petollisuus maailmaan, koska ihmisiä jotenkin ahdistettiin, eli he tahtoivat tehdä tyrannille jotain mielennouteeksi, antoivat he kiville ja puille senkaltaisen nimen, kuin ei pitänyt."],[14,22,"Sitte ei he siihen tyytyneet, että he Jumalan tunnosta erehtyivät, vaan vaikka he elivät senkaltaisessa tyhmässä ja hullussa menossa, kutsuivat he kuitenkin senkaltaisen sodan ja vahingon rauhaksi.","Sitte ei he siihen tyytyneet, että he Jumalan tunnosta erehtyivät, vaan vaikka he elivät senkaltaisessa tyhmässä ja hullussa menossa, kutsuivat he kuitenkin senkaltaisen sodan ja vahingon rauhaksi."],[14,23,"Sillä taikka he lapsensa tappavat uhriksi, eli pitävät jonkun jumalanpalveluksen, jota ei tarvita mainittaa, taikka harjoittavat itsiänsä ylönsyömisessä pahalla tavalla,","Sillä taikka he lapsensa tappavat uhriksi, eli pitävät jonkun jumalanpalveluksen, jota ei tarvita mainittaa, taikka harjoittavat itsiänsä ylönsyömisessä pahalla tavalla,"],[14,24,"Ja ei ole heillä enempi puhdasta elämää aviokäskyssä, vaan toinen tappaa toisen petoksella, eli murheelliseksi tekee huoruudella,","Ja ei ole heillä enempi puhdasta elämää aviokäskyssä, vaan toinen tappaa toisen petoksella, eli murheelliseksi tekee huoruudella,"],[14,25,"Ja heidän seassansa käy kaikki sekaisin: veri, murha, varkaus, petos, vilppi, vaatimus, väärä vala, hurskasten levottomuus,","Ja heidän seassansa käy kaikki sekaisin: veri, murha, varkaus, petos, vilppi, vaatimus, väärä vala, hurskasten levottomuus,"],[14,26,"Kiittämättömyys, nuorten sydänten pahennus, mykät synnit, sukurutsaus, huoruus ja salavuoteus.","Kiittämättömyys, nuorten sydänten pahennus, mykät synnit, sukurutsaus, huoruus ja salavuoteus."],[14,27,"Sillä häpiällisten epäjumalain palvelus on alku, syy ja loppu kaikkeen pahuuteen.","Sillä häpiällisten epäjumalain palvelus on alku, syy ja loppu kaikkeen pahuuteen."],[14,28,"Jos he pyhäpäivää pitävät, niin he tekevät kuin hullut; jos he ennustavat, niin se on kaikki valhe; ei he oikein elä, ja ovat nopsat valalla pettämään.","Jos he pyhäpäivää pitävät, niin he tekevät kuin hullut; jos he ennustavat, niin se on kaikki valhe; ei he oikein elä, ja ovat nopsat valalla pettämään."],[14,29,"Sillä he uskovat hengettömäin jumalten päälle, niin ei he pelkää vahinkoa, kuin he vannovat väärin.","Sillä he uskovat hengettömäin jumalten päälle, niin ei he pelkää vahinkoa, kuin he vannovat väärin."],[14,30,"Kuitenkin oikein heille se tapahtuu, sekä ettei heillä ole oikiaa tietoa Jumalasta, että he epäjumalista ottavat vaarin, ja että he vannovat väärin, ja ei he pyhästä lukua pidä.","Kuitenkin oikein heille se tapahtuu, sekä ettei heillä ole oikiaa tietoa Jumalasta, että he epäjumalista ottavat vaarin, ja että he vannovat väärin, ja ei he pyhästä lukua pidä."],[14,31,"Sillä jumalattomain pahuus saa lopun, ei siitä vallasta, joka heillä on vannoissansa, vaan siitä rangaistuksesta, jonka he synnillänsä ansaitsevat.","Sillä jumalattomain pahuus saa lopun, ei siitä vallasta, joka heillä on vannoissansa, vaan siitä rangaistuksesta, jonka he synnillänsä ansaitsevat."],[15,1,"Mutta sinä meidän Jumalamme olet armollinen, vakaa ja kärsivällinen, ja hallitset kaikki laupiudella.","Mutta sinä meidän Jumalamme olet armollinen, vakaa ja kärsivällinen, ja hallitset kaikki laupiudella."],[15,2,"Ja jos me syntiä teemme, olemme me kuitenkin sinun, ja tunnemme sinun voimas; mutta että me sen tiedämme, niin emme tahdo syntiä tehdä; sillä me pidetään sinun omanas.","Ja jos me syntiä teemme, olemme me kuitenkin sinun, ja tunnemme sinun voimas; mutta että me sen tiedämme, niin emme tahdo syntiä tehdä; sillä me pidetään sinun omanas."],[15,3,"Mutta tuta sinua, on täydellinen vanhurskaus, ja tietää sinun voimas, on ijankaikkisen elämän juuri.","Mutta tuta sinua, on täydellinen vanhurskaus, ja tietää sinun voimas, on ijankaikkisen elämän juuri."],[15,4,"Sillä ei ihmisen pahat aivoitukset meitä niin viettele, eikä maalarin turha työ, kirjava ja monenkarvainen kuva,","Sillä ei ihmisen pahat aivoitukset meitä niin viettele, eikä maalarin turha työ, kirjava ja monenkarvainen kuva,"],[15,5,"Jonka muoto pahentaa ymmärtämättömät, ja jotka pahaa mielellänsä tekevät, rakastavat hengettömiä ja kuolleita kuvia.","Jonka muoto pahentaa ymmärtämättömät, ja jotka pahaa mielellänsä tekevät, rakastavat hengettömiä ja kuolleita kuvia."],[15,6,"Senkaltaisia hedelmiä ovat he mahdolliset saamaan, sekä ne, jotka niitä tekevät, että ne, jotka niitä ikävöitsevät ja palvelevat.","Senkaltaisia hedelmiä ovat he mahdolliset saamaan, sekä ne, jotka niitä tekevät, että ne, jotka niitä ikävöitsevät ja palvelevat."],[15,7,"Jos savenvalaja, joka pehmeää savea vaivalla valmistaa, tekee kaikkinaiset astiat meidän tarpeeksemme; mutta hän tekee siitä samasta savesta sekä ne astiat, jotka puhtauteen että saastaisuuteen sopivat; mutta mihinkä kukin pitää pantaman, se on savenvalajalla.","Jos savenvalaja, joka pehmeää savea vaivalla valmistaa, tekee kaikkinaiset astiat meidän tarpeeksemme; mutta hän tekee siitä samasta savesta sekä ne astiat, jotka puhtauteen että saastaisuuteen sopivat; mutta mihinkä kukin pitää pantaman, se on savenvalajalla."],[15,8,"Mutta se on viheliäinen työ, kuin hän siitä savesta voimattoman jumalan tekee, ja on kuitenkin itse, ei paljoa ennen, maasta tehty, Ja vähän hetken perästä menee sinne jälleen, josta hän otettu on, koska sielu, joka hänellä oli, häneltä otetaan pois.","Mutta se on viheliäinen työ, kuin hän siitä savesta voimattoman jumalan tekee, ja on kuitenkin itse, ei paljoa ennen, maasta tehty, Ja vähän hetken perästä menee sinne jälleen, josta hän otettu on, koska sielu, joka hänellä oli, häneltä otetaan pois."],[15,9,"Mutta ei hänen murheensa siinä ole, että hänen työtä tekemän pitää, eikä että hänellä on niin lyhyt ikä, vaan että hän kilvoittelis kultaja hopiaseppäin kanssa, että hän tekis vaskenvalajan tavalla, ja pitää sen kunniana, että hän petollista työtä tekee.","Mutta ei hänen murheensa siinä ole, että hänen työtä tekemän pitää, eikä että hänellä on niin lyhyt ikä, vaan että hän kilvoittelis kultaja hopiaseppäin kanssa, että hän tekis vaskenvalajan tavalla, ja pitää sen kunniana, että hän petollista työtä tekee."],[15,10,"Sillä hänen sydämensä ajatukset ovat kuin tuhka, ja hänen toivonsa on huonompi maata, ja hänen elämänsä ylönkatsottu kuin savi;","Sillä hänen sydämensä ajatukset ovat kuin tuhka, ja hänen toivonsa on huonompi maata, ja hänen elämänsä ylönkatsottu kuin savi;"],[15,11,"Ettei hän tuntenut sitä, jo. ka hänen tehnyt oli, ja antoi hänelle sielun, joka hänessä vaikuttaa, ja puhalsi häneen elävän hengen.","Ettei hän tuntenut sitä, jo. ka hänen tehnyt oli, ja antoi hänelle sielun, joka hänessä vaikuttaa, ja puhalsi häneen elävän hengen."],[15,12,"He pitivät ihmisen elämän tyhjänä ja ihmisen menon kaupantekona, sanoen: aina pitää voittoa etsittämän pahallakin kalulla.","He pitivät ihmisen elämän tyhjänä ja ihmisen menon kaupantekona, sanoen: aina pitää voittoa etsittämän pahallakin kalulla."],[15,13,"Nämät tietävät kaiketi kyllä, että he syntiä tekevät, koska he senkaltaisia turhia kappaleita ja kuvia maasta ja savesta tekevät.","Nämät tietävät kaiketi kyllä, että he syntiä tekevät, koska he senkaltaisia turhia kappaleita ja kuvia maasta ja savesta tekevät."],[15,14,"Mutta he ovat tyhmemmät ja viheliäisemmät kuin lapsi, sinun kansas viholliset, jotka heitä sortavat,","Mutta he ovat tyhmemmät ja viheliäisemmät kuin lapsi, sinun kansas viholliset, jotka heitä sortavat,"],[15,15,"Että he kaikki pakanain epäjumalat jumalina pitävät, joiden silmät ei näe, ja heidän nenänsä ei haista, eikä heidän korvansa kuule, heidän sormensa käsissänsä ei tunne, ja heidän jalkansa ovat sangen hitaat käymään.","Että he kaikki pakanain epäjumalat jumalina pitävät, joiden silmät ei näe, ja heidän nenänsä ei haista, eikä heidän korvansa kuule, heidän sormensa käsissänsä ei tunne, ja heidän jalkansa ovat sangen hitaat käymään."],[15,16,"Sillä ihminen on tehnyt heidät, ja joka hengen saanut on, on valmistanut heitä; mutta ihminen ei taida tehdä sitä, joka hänen kaltaisensa on, paljoa vähemmin Jumalaa.","Sillä ihminen on tehnyt heidät, ja joka hengen saanut on, on valmistanut heitä; mutta ihminen ei taida tehdä sitä, joka hänen kaltaisensa on, paljoa vähemmin Jumalaa."],[15,17,"Ja että hän kuolevainen on, niin hän kuolleen tekee jumalattomilla käsillänsä; hän on itse parempi kuin se, jota hän palvelee; sillä hän itse elää, mutta se ei koskaan.","Ja että hän kuolevainen on, niin hän kuolleen tekee jumalattomilla käsillänsä; hän on itse parempi kuin se, jota hän palvelee; sillä hän itse elää, mutta se ei koskaan."],[15,18,"Sikälikin palvelevat he myös kaikkein kauheimpia petoja: jos he muihin järjettömiin luontokappaleihin verrataan, niin he ovat paljoa pahemmat.","Sikälikin palvelevat he myös kaikkein kauheimpia petoja: jos he muihin järjettömiin luontokappaleihin verrataan, niin he ovat paljoa pahemmat."],[15,19,"Sillä ei ne ole aljut niinkuin muut eläimet, jotka ovat suloiset nähdä, ja ei ole Jumalalta ylistetyt eli siunatut.","Sillä ei ne ole aljut niinkuin muut eläimet, jotka ovat suloiset nähdä, ja ei ole Jumalalta ylistetyt eli siunatut."],[16,1,"Sentähden he senkaltaisilla rangaistiin, joita he ansainneet olivat, niin että he paljoilta pedoilta vaivattiin.","Sentähden he senkaltaisilla rangaistiin, joita he ansainneet olivat, niin että he paljoilta pedoilta vaivattiin."],[16,2,"Jota vitsausta vastaan sinä teit kansalles hyvää, ja valmistit heille himoruokaa, peltokanoja ravinnoksi, jota he himoitsivat,","Jota vitsausta vastaan sinä teit kansalles hyvää, ja valmistit heille himoruokaa, peltokanoja ravinnoksi, jota he himoitsivat,"],[16,3,"Että ne, jotka sitä ruokaa himoinneet olivat, piti senkaltaisten annettuin ja säättyin peltokanain kautta oppiman itsensä pitämään pois luonnollisista tarpeista; mutta muut, joilla vähä aikaa puuttumus oli, piti uudesta elatuksesta osallisiksi tuleman.","Että ne, jotka sitä ruokaa himoinneet olivat, piti senkaltaisten annettuin ja säättyin peltokanain kautta oppiman itsensä pitämään pois luonnollisista tarpeista; mutta muut, joilla vähä aikaa puuttumus oli, piti uudesta elatuksesta osallisiksi tuleman."],[16,4,"Sillä sen piti niin tapahtuman, että heille, jotka niin julmasti tekivät, piti senkaltainen puuttumus tuleman, joka ei pitänyt lakkaaman; mutta näille ainoastaan osoitettiin, kuinka heidän vihollisensa tulivat vaivatuksi.","Sillä sen piti niin tapahtuman, että heille, jotka niin julmasti tekivät, piti senkaltainen puuttumus tuleman, joka ei pitänyt lakkaaman; mutta näille ainoastaan osoitettiin, kuinka heidän vihollisensa tulivat vaivatuksi."],[16,5,"Tulivat myös näille pahat ja julmat pedot ja pahoilta kärmeiltä pistettiin ja turmeltiin:","Tulivat myös näille pahat ja julmat pedot ja pahoilta kärmeiltä pistettiin ja turmeltiin:"],[16,6,"Ei kuitenkaan ollut se vitsaus kauvan, vaan he olivat vähän aikaa peljätetyt parannukseen; sillä heillä oli terveyden merkki, että heidän piti ajatteleman sinun käskyjäs sinun laissas.","Ei kuitenkaan ollut se vitsaus kauvan, vaan he olivat vähän aikaa peljätetyt parannukseen; sillä heillä oli terveyden merkki, että heidän piti ajatteleman sinun käskyjäs sinun laissas."],[16,7,"Sillä jotka käänsivät itsensä sen merkin puoleen, ne tulivat terveeksi, ei katsomisella,","Sillä jotka käänsivät itsensä sen merkin puoleen, ne tulivat terveeksi, ei katsomisella,"],[16,8,"Vaan sinun kauttas, joka olet kaikkein vapahtaja; jolla sinä osoitit meidän vihollisillemme, että sinä olet se, joka autat kaikesta pahasta.","Vaan sinun kauttas, joka olet kaikkein vapahtaja; jolla sinä osoitit meidän vihollisillemme, että sinä olet se, joka autat kaikesta pahasta."],[16,9,"Mutta ne heinäsirkoilta ja kärpäsiltä kuoliaaksi purtiin, ja ei taitaneet apua löytää hengellensä; sillä he olivat sen ansainneet, että heidän piti sillä vaivatuksi tuleman.","Mutta ne heinäsirkoilta ja kärpäsiltä kuoliaaksi purtiin, ja ei taitaneet apua löytää hengellensä; sillä he olivat sen ansainneet, että heidän piti sillä vaivatuksi tuleman."],[16,10,"Mutta sinun lapsias ei taitaneet ne myrkylliset lohikärmetten hampaat vahingoittaa; sillä sinun laupiutes tuli heille avuksi ja paransi heitä.","Mutta sinun lapsias ei taitaneet ne myrkylliset lohikärmetten hampaat vahingoittaa; sillä sinun laupiutes tuli heille avuksi ja paransi heitä."],[16,11,"Sillä sentähden he niin rangaistiin ja kohta parattiin jälleen, että he oppisivat ajattelemaan sinun sanaas, ja ettei he niin syvältä unhotukseen tulisi, vaan pysyisivät huikentelematta sinun hyvissä töissäs.","Sillä sentähden he niin rangaistiin ja kohta parattiin jälleen, että he oppisivat ajattelemaan sinun sanaas, ja ettei he niin syvältä unhotukseen tulisi, vaan pysyisivät huikentelematta sinun hyvissä töissäs."],[16,12,"Sillä ei yrtit eikä voiteet heitä parantaneet, vaan sinun sanas, Herra, joka kaikki parantaa.","Sillä ei yrtit eikä voiteet heitä parantaneet, vaan sinun sanas, Herra, joka kaikki parantaa."],[16,13,"Sillä sinun hallussas on sekä elämä että kuolema, ja sinä johdatat helvetin portille, ja sieltä ylös jälleen.","Sillä sinun hallussas on sekä elämä että kuolema, ja sinä johdatat helvetin portille, ja sieltä ylös jälleen."],[16,14,"Mutta jos ihminen jonkun tappaa pahuudellansa, niin ei hän taida tuoda jälleen henkeä, joka siitä on lähtenyt, eli palauttaa sielua, joka eroitettu on.","Mutta jos ihminen jonkun tappaa pahuudellansa, niin ei hän taida tuoda jälleen henkeä, joka siitä on lähtenyt, eli palauttaa sielua, joka eroitettu on."],[16,15,"Mutta mahdotoin on välttää sinun kättäs.","Mutta mahdotoin on välttää sinun kättäs."],[16,16,"Sillä jumalattomat, jotka ei tahtoneet sinua tuta, hosuttiin sinun voimallisella käsivarrellas, kuin he hirmuisella sateella, rakeella, vedellä, jota ei he paeta taitaneet, vaivattiin, ja tulella kulutettiin.","Sillä jumalattomat, jotka ei tahtoneet sinua tuta, hosuttiin sinun voimallisella käsivarrellas, kuin he hirmuisella sateella, rakeella, vedellä, jota ei he paeta taitaneet, vaivattiin, ja tulella kulutettiin."],[16,17,"Ja se oli kaikkein kamalin, että tuli enimmästi paloi vedessä, joka kuitenkin kaikki sammuttaa; sillä maailma sotii vanhurskasten edestä.","Ja se oli kaikkein kamalin, että tuli enimmästi paloi vedessä, joka kuitenkin kaikki sammuttaa; sillä maailma sotii vanhurskasten edestä."],[16,18,"Toisinaan oli tulen liekki niin masia, ettei se polttanut niitä petoja, jotka jumalattomille lähetettiin, vaan että heidän itse nähdä täytyi heitänsä Jumalan tuomiolta niin rangaistavan.","Toisinaan oli tulen liekki niin masia, ettei se polttanut niitä petoja, jotka jumalattomille lähetettiin, vaan että heidän itse nähdä täytyi heitänsä Jumalan tuomiolta niin rangaistavan."],[16,19,"Toisinaan paloi liekki vedessä vastoin tulen voimaa, että hän väärän suvun maan päältä hukuttais.","Toisinaan paloi liekki vedessä vastoin tulen voimaa, että hän väärän suvun maan päältä hukuttais."],[16,20,"Sitä vastaan ruokit sinä kansas enkelein rualla, ja lähetit leipää taivaasta ilman työtä valmistettua, joka taisi antaa kaikkinaista himoa, ja oli jokaiselle hänen makunsa jälkeen.","Sitä vastaan ruokit sinä kansas enkelein rualla, ja lähetit leipää taivaasta ilman työtä valmistettua, joka taisi antaa kaikkinaista himoa, ja oli jokaiselle hänen makunsa jälkeen."],[16,21,"Sillä jos sinuun turvataan, ilmoittaa se sinun lapsilles, kuinka makia sinä olet, ja jokainen teki siitä, mitä hän tahtoi, niinkuin hänen himonsa oli, että se niin ja niin maisti.","Sillä jos sinuun turvataan, ilmoittaa se sinun lapsilles, kuinka makia sinä olet, ja jokainen teki siitä, mitä hän tahtoi, niinkuin hänen himonsa oli, että se niin ja niin maisti."],[16,22,"Mutta näille pysyi lumi ja jää sulamatta tulessa, että he olisivat ymmärtäneet, kuinka tuli, joka rakeissa paloi, ja sateessa leimahti, turmeli vihollisten hedelmät.","Mutta näille pysyi lumi ja jää sulamatta tulessa, että he olisivat ymmärtäneet, kuinka tuli, joka rakeissa paloi, ja sateessa leimahti, turmeli vihollisten hedelmät."],[16,23,"Että vanhurskaat olisivat ravituksi tulleet, täytyi sen voimiansa unohtaa.","Että vanhurskaat olisivat ravituksi tulleet, täytyi sen voimiansa unohtaa."],[16,24,"Sillä koska luontokappale sinua palvelee niinkuin Luojaansa, on se voimallinen rankaisemaan vääriä, ja asettaa itsensä niille hyväksi, jotka uskovat sinun päälles.","Sillä koska luontokappale sinua palvelee niinkuin Luojaansa, on se voimallinen rankaisemaan vääriä, ja asettaa itsensä niille hyväksi, jotka uskovat sinun päälles."],[16,25,"Sen tähden se antoi itsensä silloin moneksi muuttaa, ja oli sinun lahjalles kuuliainen, joka kaikki ravitsee, itse kunkin tahtonsa jälkeen, niinknin joku sitä tarvitsi.","Sen tähden se antoi itsensä silloin moneksi muuttaa, ja oli sinun lahjalles kuuliainen, joka kaikki ravitsee, itse kunkin tahtonsa jälkeen, niinknin joku sitä tarvitsi."],[16,26,"Että sinun lapses, joita sinä, Herra, rakastit, oppisivat, ettei kasvanut hedelmä elätä ihmistä, vaan sinun sanas ne ravitsee, jotka uskovat sinun päälles.","Että sinun lapses, joita sinä, Herra, rakastit, oppisivat, ettei kasvanut hedelmä elätä ihmistä, vaan sinun sanas ne ravitsee, jotka uskovat sinun päälles."],[16,27,"Sillä se, joka ei tulelta kulutettu, suli kohta vähästä auringon paisteesta, koska se palavaksi tuli,","Sillä se, joka ei tulelta kulutettu, suli kohta vähästä auringon paisteesta, koska se palavaksi tuli,"],[16,28,"Että ilmoitettaisiin, että sinua pitää kiitettämän jo ennenkuin aurinko nousee, ja astuttaman sinun etees päivän valjetessa.","Että ilmoitettaisiin, että sinua pitää kiitettämän jo ennenkuin aurinko nousee, ja astuttaman sinun etees päivän valjetessa."],[16,29,"Sillä kiittämättömän ihmisen toivo pitää hukkuman niinkuin härmä talvella, ja vuotaman pois niinkuin kelvotoin vesi.","Sillä kiittämättömän ihmisen toivo pitää hukkuman niinkuin härmä talvella, ja vuotaman pois niinkuin kelvotoin vesi."],[17,1,"Suuret ja sanomattomat ovat sinun tuomios, Herra; sentähden ovat myös tyhmät ihmiset erehtyneet.","Suuret ja sanomattomat ovat sinun tuomios, Herra; sentähden ovat myös tyhmät ihmiset erehtyneet."],[17,2,"Sillä koska ne väärät luulivat polkevansa pyhän kansan, tulivat he pimeydellä sidotuksi, ja pitkällä yöltä vangituksi, ja niinkuin karkurit olivat he suljetut katon alla ijankaikkiselta viisaudelta.","Sillä koska ne väärät luulivat polkevansa pyhän kansan, tulivat he pimeydellä sidotuksi, ja pitkällä yöltä vangituksi, ja niinkuin karkurit olivat he suljetut katon alla ijankaikkiselta viisaudelta."],[17,3,"Ja kuin he luulivat syntinsä salatuksi ja pimiän peitteen alla unhotetuksi, tulivat he hirmuisesti hajoitetuksi ja peljästyksellä kauhistetuksi.","Ja kuin he luulivat syntinsä salatuksi ja pimiän peitteen alla unhotetuksi, tulivat he hirmuisesti hajoitetuksi ja peljästyksellä kauhistetuksi."],[17,4,"Ettei se loukaskaan, jossa he olivat, taitanut heitä ilman pelkoa kätkeä: silloin oli hyminä heidän ympärillänsä, josta he peljästyivät, ja hirmuiset näyt näkivät, joista he hämmästyivät.","Ettei se loukaskaan, jossa he olivat, taitanut heitä ilman pelkoa kätkeä: silloin oli hyminä heidän ympärillänsä, josta he peljästyivät, ja hirmuiset näyt näkivät, joista he hämmästyivät."],[17,5,"Ja tuli ei taitanut millään muotoa valistaa heitä, eikä kirkasten tähtien paiste taitanut sitä hirmuista yötä valistaa.","Ja tuli ei taitanut millään muotoa valistaa heitä, eikä kirkasten tähtien paiste taitanut sitä hirmuista yötä valistaa."],[17,6,"Mutta heille näkyi palavainen tuli täynnänsä kauhistusta; silloin hämmästyivät he senkaltaista peljästystä, joka kuitenkin tyhjä oli, ja ajattelivat vielä pahempaa tarjona olevan kuin he näkivät.","Mutta heille näkyi palavainen tuli täynnänsä kauhistusta; silloin hämmästyivät he senkaltaista peljästystä, joka kuitenkin tyhjä oli, ja ajattelivat vielä pahempaa tarjona olevan kuin he näkivät."],[17,7,"Noitain tieto oli tyhjä, ja sen ylistys tuli häpiäksi.","Noitain tieto oli tyhjä, ja sen ylistys tuli häpiäksi."],[17,8,"Sillä ne, jotka olivat tottuneet ajamaan pois pelkoa ja hämmästystä sairaista sieluista, tulivat se sairaiksi, niin että heidän pelkoansa pilkattiin.","Sillä ne, jotka olivat tottuneet ajamaan pois pelkoa ja hämmästystä sairaista sieluista, tulivat se sairaiksi, niin että heidän pelkoansa pilkattiin."],[17,9,"Ja jos ei senkaltaiset kauhistukset olis peljättäneet heitä,","Ja jos ei senkaltaiset kauhistukset olis peljättäneet heitä,"],[17,10,"Niin heidän olis kuitenkin täytynyt hukkua hämmästyksestä, koska pedot heidän sekaansa tulivat, ja kärmeet joukossa niin havisivat, ettei he mielellänsä katsoneet ilmaa, jota ei he kuitenkaan saaneet paitsi olla.","Niin heidän olis kuitenkin täytynyt hukkua hämmästyksestä, koska pedot heidän sekaansa tulivat, ja kärmeet joukossa niin havisivat, ettei he mielellänsä katsoneet ilmaa, jota ei he kuitenkaan saaneet paitsi olla."],[17,11,"Sillä joka niin epäileväinen on, sen tekee hänen oma pahuuntensa, joka hänestä todistaa ja tuomitsee, ja paha omatunto aina pahimmin päin ajattelee.","Sillä joka niin epäileväinen on, sen tekee hänen oma pahuuntensa, joka hänestä todistaa ja tuomitsee, ja paha omatunto aina pahimmin päin ajattelee."],[17,12,"Sillä pelko tulee siitä, ettei joku edestänsä vastata taida, ja ei tiedä mistään apua.","Sillä pelko tulee siitä, ettei joku edestänsä vastata taida, ja ei tiedä mistään apua."],[17,13,"Mutta kussa vähä lohdutusta on sydämessä, niin epäilys tekee enempi vaivaa kuin itse rangaistus.","Mutta kussa vähä lohdutusta on sydämessä, niin epäilys tekee enempi vaivaa kuin itse rangaistus."],[17,14,"Mutta ne, jotka ynnä makasivat sinä yönä, joka hirmuinen ja oikia yö oli, ja siitä kauhiasta ja syvästä helvetistä tullut oli,","Mutta ne, jotka ynnä makasivat sinä yönä, joka hirmuinen ja oikia yö oli, ja siitä kauhiasta ja syvästä helvetistä tullut oli,"],[17,15,"Toisinansa vaivattiin hirmuisilla näyillä, toisinansa niin joutuivat, ettei he muuta toivoneet kuin kuolemaa; sillä äkillinen ja tapaturmainen pelko tuli heidän päällensä,","Toisinansa vaivattiin hirmuisilla näyillä, toisinansa niin joutuivat, ettei he muuta toivoneet kuin kuolemaa; sillä äkillinen ja tapaturmainen pelko tuli heidän päällensä,"],[17,16,"Niin että kussa joku löydettiin, siinä hän oli niinkuin hän olis ollut pantu kiinni ja ilman kahleita kätketty.","Niin että kussa joku löydettiin, siinä hän oli niinkuin hän olis ollut pantu kiinni ja ilman kahleita kätketty."],[17,17,"Joko hän oli peltomies, eli paimen, eli työn tekiä korvessa, hänen täytyi, ehkä kusta hän löydettiin, kärsiä välttämätöintä ahdistusta;","Joko hän oli peltomies, eli paimen, eli työn tekiä korvessa, hänen täytyi, ehkä kusta hän löydettiin, kärsiä välttämätöintä ahdistusta;"],[17,18,"Sillä he olivat kaikki yhtäläisillä pimeyden kahleilla sidotut.","Sillä he olivat kaikki yhtäläisillä pimeyden kahleilla sidotut."],[17,19,"Jos tuuli kuului puhaltavan, eli linnut suloisesti visertelevän paksuilla oksilla, eli joku töminä juoksevaisesta vedestä eli putoovaisista ja kolisevaisista kivistä, eli että intoiset eläimet juoksivat, joita ei he nähneet, eli että hirmuiset pedot ulvoivat eli kajaus kävi vuorten raoista: niin he hämmästyivät siitä, niin että he peräti tyhmistyivät.","Jos tuuli kuului puhaltavan, eli linnut suloisesti visertelevän paksuilla oksilla, eli joku töminä juoksevaisesta vedestä eli putoovaisista ja kolisevaisista kivistä, eli että intoiset eläimet juoksivat, joita ei he nähneet, eli että hirmuiset pedot ulvoivat eli kajaus kävi vuorten raoista: niin he hämmästyivät siitä, niin että he peräti tyhmistyivät."],[17,20,"Koko maailmalla oli kirkas vaIkeus, ettei työt tulleet estetyiksi;","Koko maailmalla oli kirkas vaIkeus, ettei työt tulleet estetyiksi;"],[17,21,"Ainoasti näillä oli synkiä yö, joka oli sen pimeyden kuva, joka heille tuleva oli; mutta he olivat itsellensä suuremmaksi rasitukseksi kuin pimeys.","Ainoasti näillä oli synkiä yö, joka oli sen pimeyden kuva, joka heille tuleva oli; mutta he olivat itsellensä suuremmaksi rasitukseksi kuin pimeys."],[18,1,"Mutta sinun pyhilläs oli suuri valkeus, ja viholliset kuulivat kyllä heidän äänensä, mutta ei he nähneet heitä. lä heidän äänensä, mutta ei he nähneet heitä.","Mutta sinun pyhilläs oli suuri valkeus, ja viholliset kuulivat kyllä heidän äänensä, mutta ei he nähneet heitä. lä heidän äänensä, mutta ei he nähneet heitä."],[18,2,"Ja he ylistivät sinua, ettei he senkaltaista kärsineet, ja kiittivät, ettei he, jotka heiltä vahingoittiin, heille kostaneet, ja toivottivat, että he olisivat kaukana heistä.","Ja he ylistivät sinua, ettei he senkaltaista kärsineet, ja kiittivät, ettei he, jotka heiltä vahingoittiin, heille kostaneet, ja toivottivat, että he olisivat kaukana heistä."],[18,3,"Sitä vastaan annoit sinä näille tulipatsaan, joka heitä valisti oudolla tiellä, ja et antanut auringon vahingoittaa heitä sillä jalolla matkalla.","Sitä vastaan annoit sinä näille tulipatsaan, joka heitä valisti oudolla tiellä, ja et antanut auringon vahingoittaa heitä sillä jalolla matkalla."],[18,4,"Sillä ne olivatkin mahdolliset olemaan ilman valkeutta, ja pitikin pimeydessä niinkuin kahleissa makaaman, että he sinun lapsias vankina pitivät, jonka kautta lain katoomatoin valkeus maailmalle annettaman piti.","Sillä ne olivatkin mahdolliset olemaan ilman valkeutta, ja pitikin pimeydessä niinkuin kahleissa makaaman, että he sinun lapsias vankina pitivät, jonka kautta lain katoomatoin valkeus maailmalle annettaman piti."],[18,5,"Ja kuin he ajattelivat tappaa: pyhäin lapsia, (mutta yksi ulosheitetyistä kätkettiin heille rangaistukseksi), otit sinä suuren joukon heidän lapsistansa, ja hukutit heidät yhtä haavaa väkevässä vedessä.","Ja kuin he ajattelivat tappaa: pyhäin lapsia, (mutta yksi ulosheitetyistä kätkettiin heille rangaistukseksi), otit sinä suuren joukon heidän lapsistansa, ja hukutit heidät yhtä haavaa väkevässä vedessä."],[18,6,"Se yö oli meidän isillemme ennen ilmoitettu, että he vahvistettaisiin ja iloitsisivat lupauksesta, jonka he uskoivat.","Se yö oli meidän isillemme ennen ilmoitettu, että he vahvistettaisiin ja iloitsisivat lupauksesta, jonka he uskoivat."],[18,7,"Ja sinun kansas toivoi niin vanhurskasten autuutta ja vihollisten kadotusta.","Ja sinun kansas toivoi niin vanhurskasten autuutta ja vihollisten kadotusta."],[18,8,"Sillä kuin sinä vihollisia vaivasit, teit sinä meitä, joita tykös kutsuit, jaloksi.","Sillä kuin sinä vihollisia vaivasit, teit sinä meitä, joita tykös kutsuit, jaloksi."],[18,9,"Ja kuin jumalisten pyhät lapset uhrasivat sinulle salaisesti, ja yksimielisesti pitivät Jumalan lakia, silloin he tahtoivat niinkuin pyhät kärsiä pahaa ja hyvää toinen toisensa kanssa; ja isät veisasivat kiitosvirsiä heidän edessänsä.","Ja kuin jumalisten pyhät lapset uhrasivat sinulle salaisesti, ja yksimielisesti pitivät Jumalan lakia, silloin he tahtoivat niinkuin pyhät kärsiä pahaa ja hyvää toinen toisensa kanssa; ja isät veisasivat kiitosvirsiä heidän edessänsä."],[18,10,"Mutta sitä vastaan kuului vihollisten huuto paljo toisin, ja kuultiin vaikia valitus siellä ja täällä lapsilta.","Mutta sitä vastaan kuului vihollisten huuto paljo toisin, ja kuultiin vaikia valitus siellä ja täällä lapsilta."],[18,11,"Sillä yhtäläinen vitsaus oli herralla ja palvelialla, ja kuninkaankin täytyi sitä kärsiä kuin alamaisten.","Sillä yhtäläinen vitsaus oli herralla ja palvelialla, ja kuninkaankin täytyi sitä kärsiä kuin alamaisten."],[18,12,"Ja jokaisella heillä oli sangen monta kuollutta, Jotka yhdenkaltaisella kuolemalla kuolivat, niin ettei elävät kerinneet heitä hautaamaan; sillä yhdellä hetkellä tulivat heidän parhaat sikiänsä pois.","Ja jokaisella heillä oli sangen monta kuollutta, Jotka yhdenkaltaisella kuolemalla kuolivat, niin ettei elävät kerinneet heitä hautaamaan; sillä yhdellä hetkellä tulivat heidän parhaat sikiänsä pois."],[18,13,"Ja jotka ei ennen tahtoneet uskoa, estetyt noidilta, niiden täytyi nyt, sittekuin kaikki esikoiset tapetut olivat, tunnustaa, että tämä kansa oli Jumalan lapsi.","Ja jotka ei ennen tahtoneet uskoa, estetyt noidilta, niiden täytyi nyt, sittekuin kaikki esikoiset tapetut olivat, tunnustaa, että tämä kansa oli Jumalan lapsi."],[18,14,"Sillä koska kaikki alallansa ja vaiti olivat, ja juuri puoliyö oli,","Sillä koska kaikki alallansa ja vaiti olivat, ja juuri puoliyö oli,"],[18,15,"Tuli sinun kaikkivaltias sanas alas taivaasta kuninkaalliselta istuimelta, niinkuin voimallinen sotamies, keskelle maata, joka piti hävitettämän,","Tuli sinun kaikkivaltias sanas alas taivaasta kuninkaalliselta istuimelta, niinkuin voimallinen sotamies, keskelle maata, joka piti hävitettämän,"],[18,16,"Se terävä miekka, joka sinun ankaraa käskyäs kantoi, seisoi, ja täytti kaikki paikat kuolleilla, ja vaikka se seisoi maassa, ulottui se kuitenkin taivaasen.","Se terävä miekka, joka sinun ankaraa käskyäs kantoi, seisoi, ja täytti kaikki paikat kuolleilla, ja vaikka se seisoi maassa, ulottui se kuitenkin taivaasen."],[18,17,"Silloin peljätti heitä äkisti hirmuinen unen näky, ja tapaturmainen hämmästys tuli heidän päällensä,","Silloin peljätti heitä äkisti hirmuinen unen näky, ja tapaturmainen hämmästys tuli heidän päällensä,"],[18,18,"Ja tässä makasi yksi, ja toinen siellä puolikuolleena, niin että kyllä hänessä nähtiin, minkä syyn tähden hän kuoli.","Ja tässä makasi yksi, ja toinen siellä puolikuolleena, niin että kyllä hänessä nähtiin, minkä syyn tähden hän kuoli."],[18,19,"Sillä unet, jotka heitä peljättivät, antoivat heille kyllä tietää, ettei he olisi hukkuneet tietämättä, minkä tähden he niin pahoin rangaistiin.","Sillä unet, jotka heitä peljättivät, antoivat heille kyllä tietää, ettei he olisi hukkuneet tietämättä, minkä tähden he niin pahoin rangaistiin."],[18,20,"Tuli myös vihdoin kuoleman kiusaus vanhurskaille, ja korvessa tapahtui vahinko kansassa; mutta viha ei ollut kauvan.","Tuli myös vihdoin kuoleman kiusaus vanhurskaille, ja korvessa tapahtui vahinko kansassa; mutta viha ei ollut kauvan."],[18,21,"Sillä se nuhteetoin mies kiiruhti, joka heidän edestänsä soti, ja kantoi virkansa kilven, rukouksen ja sovinnon suitsutuksella, ja seisoi vihaa vastaan, ja lopetti sen surkeuden, jolla hän osoitti, että hän oli sinun palvelias.","Sillä se nuhteetoin mies kiiruhti, joka heidän edestänsä soti, ja kantoi virkansa kilven, rukouksen ja sovinnon suitsutuksella, ja seisoi vihaa vastaan, ja lopetti sen surkeuden, jolla hän osoitti, että hän oli sinun palvelias."],[18,22,"Mutta hän voitti sen hirmuisen menon, ei ruumiillisella väellä eli miekan voimalla, vaan sanalla paiskasi hän vaivaajan allensa, koska hän ilmoitti valan ja liiton, joka isille luvattu oli.","Mutta hän voitti sen hirmuisen menon, ei ruumiillisella väellä eli miekan voimalla, vaan sanalla paiskasi hän vaivaajan allensa, koska hän ilmoitti valan ja liiton, joka isille luvattu oli."],[18,23,"Sillä koska kuolleet lankesivat toinen toisensa päälle, seisoi hän siellä keskellä, ja asetti vihan, ja esti, ettei hän päässyt eläväin tykö.","Sillä koska kuolleet lankesivat toinen toisensa päälle, seisoi hän siellä keskellä, ja asetti vihan, ja esti, ettei hän päässyt eläväin tykö."],[18,24,"Sillä hänen pitkässä hameessansa oli kaikki kaunistus, ja isäin kunnia neljässä kivirivissä kaivettu, ja sinun jaloutes hänen päänsä lakissa.","Sillä hänen pitkässä hameessansa oli kaikki kaunistus, ja isäin kunnia neljässä kivirivissä kaivettu, ja sinun jaloutes hänen päänsä lakissa."],[18,25,"Senkaltaisista täytyi turmelian paeta ja sitä peljätä; sillä siinä oli kyllä, että viha ainoasti sillä koeteltiin.","Senkaltaisista täytyi turmelian paeta ja sitä peljätä; sillä siinä oli kyllä, että viha ainoasti sillä koeteltiin."],[19,1,"Mutta jumalattomille tuli viha ilman laupiutta loppuun asti; sillä kyllä hän ennen tiesi, mitä heidän vasta tekemän piti,","Mutta jumalattomille tuli viha ilman laupiutta loppuun asti; sillä kyllä hän ennen tiesi, mitä heidän vasta tekemän piti,"],[19,2,"Että heidän piti käskemän heidän mennä matkaansa, ja johdattaman heitä visusti, että heidän piti sitä katuman, ja ajaman heitä takaa.","Että heidän piti käskemän heidän mennä matkaansa, ja johdattaman heitä visusti, että heidän piti sitä katuman, ja ajaman heitä takaa."],[19,3,"Sillä kuin he vielä murehtivat ja valitusitkua pitivät kuolleiden hautain tykönä, joutuivat he toiseen tyhmään aivoitukseen, että he tahtoivat heitä ajaa takaa niinkuin karkureita, joita he kuitenkin olivat ajaneet pois suurella rukouksella.","Sillä kuin he vielä murehtivat ja valitusitkua pitivät kuolleiden hautain tykönä, joutuivat he toiseen tyhmään aivoitukseen, että he tahtoivat heitä ajaa takaa niinkuin karkureita, joita he kuitenkin olivat ajaneet pois suurella rukouksella."],[19,4,"Mutta sen piti niin käymän, että he tulivat hukatuksi senkaltaisella lopulla, jonka he ansainneet olivat, ja unhottivat, mitä heille oli tapahtunut, että he saivat täydellisen vitsauksen, joka heille vielä tarjona oli,","Mutta sen piti niin käymän, että he tulivat hukatuksi senkaltaisella lopulla, jonka he ansainneet olivat, ja unhottivat, mitä heille oli tapahtunut, että he saivat täydellisen vitsauksen, joka heille vielä tarjona oli,"],[19,5,"Ja sinun kansas piti vaeltaman ihmeellistä matkaa, mutta nämät uuden kuolemisen tavan löytämän.","Ja sinun kansas piti vaeltaman ihmeellistä matkaa, mutta nämät uuden kuolemisen tavan löytämän."],[19,6,"Sillä kaikki luontokappaleet, joilla oma luonto oli, muuttivat itsensä sinun käskys perään, jota he palvelivat, että sinun lapses ilman vahinkoa olisivat vaeltaneet.","Sillä kaikki luontokappaleet, joilla oma luonto oli, muuttivat itsensä sinun käskys perään, jota he palvelivat, että sinun lapses ilman vahinkoa olisivat vaeltaneet."],[19,7,"Pilvi oli siellä ja varjosi leirin: jossa ennen vesi oli, näkyi kuiva maa, Punaisesta merestä, tuli tie ilman estettä, ja väkevistä aalloista viheriäinen keto,","Pilvi oli siellä ja varjosi leirin: jossa ennen vesi oli, näkyi kuiva maa, Punaisesta merestä, tuli tie ilman estettä, ja väkevistä aalloista viheriäinen keto,"],[19,8,"Josta kaikki kansa kävi, jotka sinun kätes alla suojeltiin. nähden senkaltaista ihmeellistä ihmettä,","Josta kaikki kansa kävi, jotka sinun kätes alla suojeltiin. nähden senkaltaista ihmeellistä ihmettä,"],[19,9,"Ja kävivät niinkuin hevoset laitumella, ja hyppäsivät niin: kuin karitsat, ja kiittivät sinua l Herra, joka heitä pelastit.","Ja kävivät niinkuin hevoset laitumella, ja hyppäsivät niin: kuin karitsat, ja kiittivät sinua l Herra, joka heitä pelastit."],[19,10,"Sillä he johdattivat mieleensä, mitä heille oli tapahtunut heidän viheliäisyydessänsä, kuinka maa, sen siassa kuin hän ennen antoi eläimiä, nyt antoi kärpäsiä ja vesi antoi paljo sammakoita kalain edestä.","Sillä he johdattivat mieleensä, mitä heille oli tapahtunut heidän viheliäisyydessänsä, kuinka maa, sen siassa kuin hän ennen antoi eläimiä, nyt antoi kärpäsiä ja vesi antoi paljo sammakoita kalain edestä."],[19,11,"Senjälkeen näkivät he myös uuden lintuin lajin, kuin he himoitsivat, ja anoivat herkullista ruokaa.","Senjälkeen näkivät he myös uuden lintuin lajin, kuin he himoitsivat, ja anoivat herkullista ruokaa."],[19,12,"Sillä peltokanat tulivat heidän tykönsä merestä, lakkauttamaan heidän himoansa. Tuli myös rangaistus syntisille ihmeen kanssa, joka väkevällä pitkäisen leimauksella tapahtui; sillä se oli. oikein, että he senkaltaista kärsivät tuimuutensa tähden, että he olivat pahoin tehneet vieraita vastaan.","Sillä peltokanat tulivat heidän tykönsä merestä, lakkauttamaan heidän himoansa. Tuli myös rangaistus syntisille ihmeen kanssa, joka väkevällä pitkäisen leimauksella tapahtui; sillä se oli. oikein, että he senkaltaista kärsivät tuimuutensa tähden, että he olivat pahoin tehneet vieraita vastaan."],[19,13,"Muutamat, kuin ne tulivat, jotka ei tietäneet, kuhunka heidän piti menemän, ei ottaneet heitä vastaan; mutta muutamat vaativat vieraita, jotka heille olivat hyvää tehneet, orjuuteen.","Muutamat, kuin ne tulivat, jotka ei tietäneet, kuhunka heidän piti menemän, ei ottaneet heitä vastaan; mutta muutamat vaativat vieraita, jotka heille olivat hyvää tehneet, orjuuteen."],[19,14,"(Ja ei siinä ainoasti, vaan yksi rangaistus piti tuleman heidän päällensä, että he pahaa tekivät muukalaisille.)","(Ja ei siinä ainoasti, vaan yksi rangaistus piti tuleman heidän päällensä, että he pahaa tekivät muukalaisille.)"],[19,15,"Mutta muutamat vaivasivat suurella tuskalla niitä, jotka he ottivat ilolla vastaan, ja antoivat kanssansa nautita kaupungin oikeutta.","Mutta muutamat vaivasivat suurella tuskalla niitä, jotka he ottivat ilolla vastaan, ja antoivat kanssansa nautita kaupungin oikeutta."],[19,16,"Mutta ne myös tulivat sokeudella lyödyksi (niinkuin ne, vanhurskaan oven edessä) paksulla pimeydellä saavutettiin, että jokainen etsi tietä omaan oveensa.","Mutta ne myös tulivat sokeudella lyödyksi (niinkuin ne, vanhurskaan oven edessä) paksulla pimeydellä saavutettiin, että jokainen etsi tietä omaan oveensa."],[19,17,"Sillä elementit kävivät toinen toisensa sekaan edestakaisin, niinkuin kanteleen kielet soivat toinen toisensa jälkeen ja kauniisti kuuluvat, niinkuin silmäin edessä nähdään.","Sillä elementit kävivät toinen toisensa sekaan edestakaisin, niinkuin kanteleen kielet soivat toinen toisensa jälkeen ja kauniisti kuuluvat, niinkuin silmäin edessä nähdään."],[19,18,"Sillä joka tottunut oli maalla olemaan, se oli vedessä, ja joka vedessä oli tottunut olemaan, se kävi maalla.","Sillä joka tottunut oli maalla olemaan, se oli vedessä, ja joka vedessä oli tottunut olemaan, se kävi maalla."],[19,19,"Tuli oli voimallinen vedessä vastoin luontoansa, vesi unhotti voimansa sammuttamisessa.","Tuli oli voimallinen vedessä vastoin luontoansa, vesi unhotti voimansa sammuttamisessa."],[19,20,"Sitä vastaan tulen liekki ei kuluttanut kuolevaisten eläimien lihaa, jotka siinä kävivät, eikä sulattanut kuolematointa ruokaa, joka kuitenkin niinkuin jää kohta suli.","Sitä vastaan tulen liekki ei kuluttanut kuolevaisten eläimien lihaa, jotka siinä kävivät, eikä sulattanut kuolematointa ruokaa, joka kuitenkin niinkuin jää kohta suli."],[19,21,"Herra, sinä olet kaikissa kunnioittanut ja jaloksi tehnyt sinun kansas, ja et katsonut heitä ylön, vaan aina ja joka paikassa olet ollut heille avullinen. Viisauden kirjan loppu.","Herra, sinä olet kaikissa kunnioittanut ja jaloksi tehnyt sinun kansas, ja et katsonut heitä ylön, vaan aina ja joka paikassa olet ollut heille avullinen. Viisauden kirjan loppu."]]}};